import { StyleSheet, TextInput, View } from "react-native";

import { Pastel } from "@/constants/pastel";
import { Font } from "@/constants/typography";

export type DateTimeFieldsProps = {
  dateText: string;
  timeText: string;
  onChangeDate: (v: string) => void;
  onChangeTime: (v: string) => void;
};

// Variante native (iOS/Android) : saisie texte JJ/MM/AAAA + HH:MM (format attendu par parseEventDateTimeInputs).
export function DateTimeFields({ dateText, timeText, onChangeDate, onChangeTime }: DateTimeFieldsProps) {
  return (
    <View style={styles.row}>
      <TextInput
        value={dateText}
        onChangeText={onChangeDate}
        placeholder="JJ/MM/AAAA"
        placeholderTextColor={Pastel.textMuted}
        style={[styles.input, styles.dateInput]}
        autoCapitalize="none"
        keyboardType="numbers-and-punctuation"
      />
      <TextInput
        value={timeText}
        onChangeText={onChangeTime}
        placeholder="HH:MM"
        placeholderTextColor={Pastel.textMuted}
        style={[styles.input, styles.timeInput]}
        autoCapitalize="none"
        keyboardType="numbers-and-punctuation"
      />
    </View>
  );
}

const styles = StyleSheet.create({
  row: { flexDirection: "row", gap: 10 },
  input: {
    borderWidth: 1,
    borderColor: Pastel.border,
    borderRadius: 12,
    paddingHorizontal: 14,
    paddingVertical: 12,
    fontSize: 15,
    color: Pastel.text,
    fontFamily: Font.regular,
    backgroundColor: Pastel.surface,
  },
  dateInput: { flex: 2 },
  timeInput: { flex: 1 },
});
