import { supabase } from "./supabase";

// ============================================================================
// Jovial Admin — wrappers typés des RPC analytiques (toutes gated côté SQL par
// is_platform_admin()). Un non-admin reçoit une erreur "forbidden".
// ============================================================================

export type Granularity = "day" | "week" | "month" | "year";

export type AdminKpis = {
  users_total: number;
  users_new: number;
  users_new_prev: number;
  establishments_total: number;
  establishments_new: number;
  establishments_new_prev: number;
  active_subscriptions: number;
  paying_establishments: number;
  free_establishments: number;
  mrr_cents: number;
  arr_cents: number;
  reservations_total: number;
  reservations_period: number;
  reservations_prev: number;
  events_period: number;
  from: string;
  to: string;
};

export type TimePoint = {
  bucket: string;
  value: number;
  cumulative?: number;
  cancelled?: number;
  mrr_cents?: number;
};

export type LabelCount = { label: string; count: number; mrr_cents?: number };

export type RevenueSummary = {
  mrr_cents: number;
  arr_cents: number;
  boost_volume: number;
  churned_count: number;
  active_count: number;
  churn_rate: number;
  from: string;
  to: string;
};

export type FunnelStep = { label: string; value: number };
export type SignupFunnel = { users: FunnelStep[]; establishments: FunnelStep[]; from: string; to: string };

export type EngagementSummary = {
  reservations: number;
  events: number;
  rsvps: number;
  follows: number;
  favorites: number;
  messages: number;
  club_posts: number;
  communities: number;
  from: string;
  to: string;
};

export type TopEstablishment = { venue_id: number; name: string | null; city: string | null; metric_value: number };
export type TopMetric = "reservations" | "events" | "club_activity" | "favorites";

export type ModerationStatus = "active" | "suspended" | "removed";

export type AdminEstablishmentRow = {
  venue_id: number;
  name: string | null;
  city: string | null;
  venue_type: string | null;
  is_active: boolean;
  moderation_status: ModerationStatus;
  moderation_reason: string | null;
  created_at: string;
  plan: string | null;
  sub_status: string | null;
  reservations_count: number;
  charter_accepted_at: string | null;
};

export type AdminUserRow = {
  handle: string | null;
  firstname: string | null;
  city: string | null;
  postcode: string | null;
  department: string | null;
  geo_zone: string | null;
  gender: string | null;
  age_bracket: string | null;
  role: string;
  created_at: string;
  email: string | null;
  is_premium: boolean;
  marketing_consent: boolean;
};

export type DepartmentCount = { code: string; label: string; region: string; count: number };
export type UserRevenue = { premium_active: number; unit_price_cents: number; mrr_cents: number; arr_cents: number };

export type DateRange = { from?: string | null; to?: string | null };

// --- Accès -------------------------------------------------------------------
export async function isPlatformAdmin(): Promise<boolean> {
  const { data, error } = await supabase.rpc("admin_check");
  if (error) return false;
  return data === true;
}

// --- KPI ---------------------------------------------------------------------
export async function getAdminKpis(range: DateRange = {}): Promise<AdminKpis> {
  const { data, error } = await supabase.rpc("admin_kpis", { p_from: range.from ?? null, p_to: range.to ?? null });
  if (error) throw error;
  return data as AdminKpis;
}

// --- Séries temporelles ------------------------------------------------------
async function timeseries(fn: string, range: DateRange, g: Granularity): Promise<TimePoint[]> {
  const { data, error } = await supabase.rpc(fn, { p_from: range.from ?? null, p_to: range.to ?? null, p_granularity: g });
  if (error) throw error;
  return (data ?? []) as TimePoint[];
}
export const getUsersTimeseries = (r: DateRange, g: Granularity) => timeseries("admin_timeseries_users", r, g);
export const getEstablishmentsTimeseries = (r: DateRange, g: Granularity) => timeseries("admin_timeseries_establishments", r, g);
export const getReservationsTimeseries = (r: DateRange, g: Granularity) => timeseries("admin_timeseries_reservations", r, g);
export const getRevenueTimeseries = (r: DateRange, g: Granularity) => timeseries("admin_revenue_timeseries", r, g);

// --- Répartitions ------------------------------------------------------------
async function breakdown(fn: string, params: Record<string, unknown> = {}): Promise<LabelCount[]> {
  const { data, error } = await supabase.rpc(fn, params);
  if (error) throw error;
  return (data ?? []) as LabelCount[];
}
export const getUsersByAge = () => breakdown("admin_breakdown_users_age");
export const getUsersByGender = () => breakdown("admin_breakdown_users_gender");
export const getUsersByZone = () => breakdown("admin_breakdown_users_zone");
export const getUsersByCity = (limit = 15) => breakdown("admin_breakdown_users_city", { p_limit: limit });
export const getEstablishmentsByType = () => breakdown("admin_breakdown_establishments_type");
export const getEstablishmentsByCity = (limit = 15) => breakdown("admin_breakdown_establishments_city", { p_limit: limit });
export const getSubscriptionsByPlan = () => breakdown("admin_breakdown_subscriptions_plan");
export const getReservationsByStatus = (r: DateRange = {}) => breakdown("admin_breakdown_reservations_status", { p_from: r.from ?? null, p_to: r.to ?? null });
export const getTopZones = (limit = 10) => breakdown("admin_top_zones", { p_limit: limit });

// --- Géographie par département / région (Round 24) ---
export const getUsersByRegion = () => breakdown("admin_breakdown_users_region");
export const getEstablishmentsByRegion = () => breakdown("admin_breakdown_establishments_region");
