import { StyleSheet, Text, type StyleProp, type TextStyle } from "react-native";
import { useRouter } from "expo-router";

import { supabase } from "@/services/supabase";
import { Pastel } from "@/constants/pastel";
import { Font } from "@/constants/typography";

// Affiche un texte en surlignant les @pseudo (teal + gras), cliquables → profil.
const MENTION_RE = /(@[a-zA-Z0-9_.-]{2,30})/g;

export function MentionText({ children, style }: { children?: string | null; style?: StyleProp<TextStyle> }) {
  const router = useRouter();

  const openHandle = async (handle: string) => {
    const { data } = await supabase.from("profiles").select("user_id").eq("handle", handle).maybeSingle();
    if (data?.user_id) router.push(`/profile/${data.user_id}` as any);
  };

  const value = String(children ?? "");
  const parts = value.split(MENTION_RE);
  return (
    <Text style={style}>
      {parts.map((part, i) => {
        if (part.startsWith("@") && part.length > 1) {
          const handle = part.slice(1);
          return (
            <Text key={`m-${i}`} style={styles.mention} onPress={() => openHandle(handle)}>
              {part}
            </Text>
          );
        }
        return <Text key={`t-${i}`}>{part}</Text>;
      })}
    </Text>
  );
}

const styles = StyleSheet.create({
  mention: { color: Pastel.teal, fontFamily: Font.bold },
});
