import { useCallback, useEffect, useState } from "react";
import { StyleSheet, Text, View } from "react-native";

import JovialAdminShell from "@/components/ui/JovialAdminShell";
import { ExportCsvButton } from "@/components/ui/ExportCsvButton";
import { getFeedback, type FeedbackRow } from "@/services/admin";
import { csvDate, type CsvColumn } from "@/utils/csv";
import { Pastel } from "@/constants/pastel";
import { Font } from "@/constants/typography";

const CAT_META: Record<string, { label: string; bg: string; color: string }> = {
  idea: { label: "Idée", bg: "#D8F0EE", color: "#2F7D73" },
  bug: { label: "Bug", bg: "#FEE2E2", color: "#B91C1C" },
  other: { label: "Autre", bg: "#EEF2F7", color: "#475569" },
};

function fmt(iso: string) {
  return new Date(iso).toLocaleDateString("fr-FR", { day: "2-digit", month: "short", year: "numeric" });
}

const FB_CSV_COLUMNS: CsvColumn<FeedbackRow>[] = [
  { label: "Catégorie", value: (r) => CAT_META[r.category]?.label ?? r.category },
  { label: "Établissement", value: (r) => r.venue_name },
  { label: "Utilisateur", value: (r) => (r.user_handle ? `@${r.user_handle}` : "") },
  { label: "Message", value: (r) => r.message },
  { label: "Statut", value: (r) => r.status },
  { label: "Reçu le", value: (r) => csvDate(r.created_at) },
];

export default function AdminFeedbackScreen() {
  const [rows, setRows] = useState<FeedbackRow[]>([]);
  const [loading, setLoading] = useState(true);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      setRows(await getFeedback());
    } catch {
      setRows([]);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { load(); }, [load]);

  return (
    <JovialAdminShell
      title="Retours établissements"
      subtitle={`${rows.length} retour${rows.length > 1 ? "s" : ""}`}
      loading={loading}
      onRefresh={load}
    >
      <ExportCsvButton rows={rows} columns={FB_CSV_COLUMNS} filenameBase="retours-etablissements" />
      {rows.length === 0 ? (
        <View style={styles.empty}>
          <Text style={styles.emptyText}>Aucun retour pour l'instant.</Text>
        </View>
      ) : (
        <View style={styles.list}>
          {rows.map((r) => {
            const cat = CAT_META[r.category] ?? CAT_META.other;
            return (
              <View key={r.id} style={styles.card}>
                <View style={styles.cardTop}>
                  <View style={[styles.badge, { backgroundColor: cat.bg }]}>
                    <Text style={[styles.badgeText, { color: cat.color }]}>{cat.label}</Text>
                  </View>
                  <Text style={styles.meta} numberOfLines={1}>
                    {r.venue_name ?? "—"}{r.user_handle ? ` · @${r.user_handle}` : ""}
                  </Text>
                  <Text style={styles.date}>{fmt(r.created_at)}</Text>
                </View>
                <Text style={styles.message}>{r.message}</Text>
              </View>
            );
          })}
        </View>
      )}
    </JovialAdminShell>
  );
}

const styles = StyleSheet.create({
  empty: { padding: 48, alignItems: "center" },
  emptyText: { fontSize: 14, color: Pastel.textMuted, includeFontPadding: false },
  list: { gap: 12 },
  card: { backgroundColor: Pastel.surface, borderRadius: 16, borderWidth: 1, borderColor: Pastel.border, padding: 16, gap: 8 },
  cardTop: { flexDirection: "row", alignItems: "center", gap: 10 },
  badge: { borderRadius: 999, paddingHorizontal: 9, paddingVertical: 3 },
  badgeText: { fontSize: 11, fontFamily: Font.extraBold, includeFontPadding: false },
  meta: { flex: 1, fontSize: 13, fontFamily: Font.semiBold, color: Pastel.text, includeFontPadding: false },
  date: { fontSize: 12, color: Pastel.textMuted, includeFontPadding: false },
  message: { fontSize: 14, color: Pastel.text, fontFamily: Font.regular, lineHeight: 21, includeFontPadding: false },
});
