import { ReactNode, useCallback, useState } from "react";
import { LayoutChangeEvent, Platform, Pressable, StyleSheet, Text, View } from "react-native";
import Svg, { Circle, G, Line, Path, Rect, Text as SvgText } from "react-native-svg";
import { Pastel } from "@/constants/pastel";
import { Font } from "@/constants/typography";

// Survol (web) ou glissé (natif) -> renvoie l'index du point sous le pointeur.
// Web : onMouseMove via getBoundingClientRect. Natif : responder + locationX.
function usePointer(mapXtoIdx: (offsetX: number) => number) {
  const [idx, setIdx] = useState<number | null>(null);
  const props: any =
    Platform.OS === "web"
      ? {
          onMouseMove: (e: any) => {
            const rect = e.currentTarget?.getBoundingClientRect?.();
            if (rect) setIdx(mapXtoIdx(e.clientX - rect.left));
          },
          onMouseLeave: () => setIdx(null),
        }
      : {
          onStartShouldSetResponder: () => true,
          onMoveShouldSetResponder: () => true,
          onResponderGrant: (e: any) => setIdx(mapXtoIdx(e.nativeEvent.locationX)),
          onResponderMove: (e: any) => setIdx(mapXtoIdx(e.nativeEvent.locationX)),
          onResponderRelease: () => setIdx(null),
          onResponderTerminate: () => setIdx(null),
        };
  return [idx, props] as const;
}

