export const PALETTE = [
  "#2B4E93", "#5CB6AC", "#F97316", "#8B5CF6", "#EC4899",
  "#10B981", "#F59E0B", "#6366F1", "#14B8A6", "#EF4444",
];

export const formatInt = (n: number) =>
  Math.round(n || 0).toString().replace(/\B(?=(\d{3})+(?!\d))/g, " ");

export const formatCompact = (n: number) => {
  const a = Math.abs(n || 0);
  if (a >= 1_000_000) return (n / 1_000_000).toFixed(a >= 10_000_000 ? 0 : 1).replace(".", ",") + "M";
  if (a >= 1_000) return (n / 1_000).toFixed(a >= 10_000 ? 0 : 1).replace(".", ",") + "k";
  return formatInt(n);
};

export const formatEuros = (cents: number) => formatInt(Math.round((cents || 0) / 100)) + " €";

export function useMeasuredWidth(initial = 320) {
  const [width, setWidth] = useState(initial);
  const onLayout = useCallback(
    (e: LayoutChangeEvent) => {
      const w = e.nativeEvent.layout.width;
      if (w && Math.abs(w - width) > 1) setWidth(w);
    },
    [width]
  );
  return [width, onLayout] as const;
}

const shortDate = (s: string) => {
  // 'YYYY-MM-DD' -> 'MM/YY'
  if (!s || s.length < 7) return s;
  return s.slice(5, 7) + "/" + s.slice(2, 4);
};

// --- ChartCard ---------------------------------------------------------------
export function ChartCard({
  title,
  subtitle,
  children,
  right,
  flex,
}: {
  title?: string;
  subtitle?: string;
  children: ReactNode;
  right?: ReactNode;
  flex?: number;
}) {
  return (
    <View style={[styles.card, flex ? { flex } : null]}>
      {title || right ? (
        <View style={styles.cardHead}>
          <View style={{ flex: 1 }}>
            {title ? <Text style={styles.cardTitle}>{title}</Text> : null}
            {subtitle ? <Text style={styles.cardSub}>{subtitle}</Text> : null}
          </View>
          {right}
        </View>
      ) : null}
      {children}
    </View>
  );
}

// --- KPIStat -----------------------------------------------------------------
export function KPIStat({
  label,
  value,
  delta,
  icon,
  accent = Pastel.primary,
  sub,
}: {
  label: string;
  value: string;
  delta?: number | null; // pourcentage de variation (ex: 0.12 = +12%)
  icon?: ReactNode;
  accent?: string;
  sub?: string; // petite ligne de contexte sous la valeur
}) {
  const hasDelta = delta !== null && delta !== undefined && isFinite(delta);
  const up = (delta ?? 0) >= 0;
  return (
    <View style={styles.kpi}>
      <View style={styles.kpiHead}>
        <Text style={styles.kpiLabel} numberOfLines={1}>{label}</Text>
        {icon}
      </View>
      <Text style={[styles.kpiValue, { color: accent }]} numberOfLines={1} adjustsFontSizeToFit>
        {value}
      </Text>
      {sub ? <Text style={styles.kpiSub} numberOfLines={2}>{sub}</Text> : null}
      {hasDelta ? (
        <View style={[styles.kpiDelta, { backgroundColor: up ? "#ECFDF5" : "#FEF2F2" }]}>
          <Text style={[styles.kpiDeltaTxt, { color: up ? "#059669" : "#DC2626" }]}>
            {up ? "▲" : "▼"} {Math.abs((delta ?? 0) * 100).toFixed(0)}%
          </Text>
        </View>
      ) : null}
    </View>
  );
}

// --- Sparkline ---------------------------------------------------------------
export function Sparkline({ data, color = Pastel.teal, height = 40 }: { data: number[]; color?: string; height?: number }) {
  const [width, onLayout] = useMeasuredWidth();
  const n = data.length;
  const max = Math.max(1, ...data);
  const pts = data.map((v, i) => {
    const x = n <= 1 ? 0 : (i / (n - 1)) * width;
    const y = height - (v / max) * (height - 4) - 2;
    return `${x},${y}`;
  });
  return (
    <View onLayout={onLayout} style={{ height }}>
      {n > 1 ? (
        <Svg width={width} height={height}>
          <Path d={`M${pts.join(" L")}`} stroke={color} strokeWidth={2} fill="none" />
        </Svg>
      ) : null}
    </View>
  );
}

// --- LineChart (+ aire optionnelle + 2e série + tooltip au survol) -----------
export function LineChart({
  data,
  height = 220,
  color = Pastel.primary,
  area = false,
  secondary,
  secondaryColor = Pastel.teal,
  yFormat = formatCompact,
  xFormat = shortDate,
  valueFormat = formatInt,
  secondaryLabel = "Annulées",
}: {
  data: { label: string; value: number }[];
  height?: number;
  color?: string;
  area?: boolean;
  secondary?: { label: string; value: number }[];
  secondaryColor?: string;
  yFormat?: (n: number) => string;
  xFormat?: (s: string) => string;
  valueFormat?: (n: number) => string;
  secondaryLabel?: string;
}) {
  const [width, onLayout] = useMeasuredWidth();
  const PL = 46, PR = 14, PT = 12, PB = 28;
  const innerW = Math.max(1, width - PL - PR);
  const innerH = Math.max(1, height - PT - PB);
  const n = data.length;
  const allVals = [...data.map((d) => d.value), ...(secondary?.map((d) => d.value) ?? [])];
  const max = Math.max(1, ...allVals);
  const x = (i: number) => PL + (n <= 1 ? innerW / 2 : (i / (n - 1)) * innerW);
  const y = (v: number) => PT + innerH - (v / max) * innerH;

  const line = (arr: { value: number }[]) => arr.map((d, i) => `${x(i)},${y(d.value)}`).join(" L");
  const grid = [0, 0.25, 0.5, 0.75, 1];
  const xTicks = n <= 1 ? [0] : [0, Math.floor((n - 1) / 3), Math.floor((2 * (n - 1)) / 3), n - 1];

  const [hover, pointer] = usePointer((offsetX) => {
    if (n <= 1) return 0;
    const innerX = Math.min(innerW, Math.max(0, offsetX - PL));
    return Math.max(0, Math.min(n - 1, Math.round((innerX / innerW) * (n - 1))));
  });
  const hv = hover !== null && hover >= 0 && hover < n ? hover : null;

  return (
    <View onLayout={onLayout} style={{ height }} {...pointer}>
      {n >= 1 ? (
        <Svg width={width} height={height}>
          {grid.map((g, i) => {
            const gy = PT + innerH - g * innerH;
            return (
              <G key={i}>
                <Line x1={PL} y1={gy} x2={width - PR} y2={gy} stroke="#EEF2F7" strokeWidth={1} />
                <SvgText x={PL - 6} y={gy + 3} fontSize={9} fill="#9CA3AF" textAnchor="end">
                  {yFormat(max * g)}
                </SvgText>
              </G>
            );
          })}
          {area && n > 1 ? (
            <Path
              d={`M${x(0)},${PT + innerH} L${line(data)} L${x(n - 1)},${PT + innerH} Z`}
              fill={color}
              fillOpacity={0.12}
            />
          ) : null}
          {n > 1 ? <Path d={`M${line(data)}`} stroke={color} strokeWidth={2.5} fill="none" /> : null}
          {secondary && secondary.length > 1 ? (
            <Path d={`M${line(secondary)}`} stroke={secondaryColor} strokeWidth={2} fill="none" strokeDasharray="4 3" />
          ) : null}
          {xTicks.map((i, k) => (
            <SvgText key={k} x={x(i)} y={height - 8} fontSize={9} fill="#9CA3AF" textAnchor="middle">
              {xFormat(data[i]?.label ?? "")}
            </SvgText>
          ))}
          {hv !== null ? (
            <G>
              <Line x1={x(hv)} y1={PT} x2={x(hv)} y2={PT + innerH} stroke="#9CA3AF" strokeWidth={1} strokeDasharray="3 3" />
              <Circle cx={x(hv)} cy={y(data[hv].value)} r={4} fill={color} stroke="#FFFFFF" strokeWidth={2} />
              {secondary && secondary[hv] ? (
                <Circle cx={x(hv)} cy={y(secondary[hv].value)} r={3.5} fill={secondaryColor} stroke="#FFFFFF" strokeWidth={1.5} />
              ) : null}
            </G>
          ) : null}
        </Svg>
      ) : null}
      {hv !== null ? (
        <View pointerEvents="none" style={[styles.tip, { left: Math.max(2, Math.min(width - 124, x(hv) - 60)) }]}>
          <Text style={styles.tipLabel}>{xFormat(data[hv].label)}</Text>
          <Text style={styles.tipValue}>{valueFormat(data[hv].value)}</Text>
          {secondary && secondary[hv] ? <Text style={styles.tipSub}>{secondaryLabel} : {valueFormat(secondary[hv].value)}</Text> : null}
        </View>
      ) : null}
    </View>
  );
}

// --- BarChart vertical (+ tooltip au survol) ---------------------------------
export function BarChart({
  data,
  height = 220,
  color = Pastel.primary,
  yFormat = formatCompact,
  xFormat = shortDate,
  valueFormat = formatInt,
}: {
  data: { label: string; value: number }[];
  height?: number;
  color?: string;
  yFormat?: (n: number) => string;
  xFormat?: (s: string) => string;
  valueFormat?: (n: number) => string;
}) {
  const [width, onLayout] = useMeasuredWidth();
  const PL = 46, PR = 14, PT = 12, PB = 28;
  const innerW = Math.max(1, width - PL - PR);
  const innerH = Math.max(1, height - PT - PB);
  const n = data.length;
  const max = Math.max(1, ...data.map((d) => d.value));
  const slot = innerW / Math.max(1, n);
  const bw = Math.min(38, slot * 0.62);
  const grid = [0, 0.5, 1];
  const xTicks = n <= 1 ? [0] : [0, Math.floor((n - 1) / 2), n - 1];

  const [hover, pointer] = usePointer((offsetX) => {
    const i = Math.floor((offsetX - PL) / slot);
    return Math.max(0, Math.min(n - 1, i));
  });
  const hv = hover !== null && hover >= 0 && hover < n ? hover : null;
  const cxOf = (i: number) => PL + slot * i + slot / 2;

  return (
    <View onLayout={onLayout} style={{ height }} {...pointer}>
      {n >= 1 ? (
        <Svg width={width} height={height}>
          {grid.map((g, i) => {
            const gy = PT + innerH - g * innerH;
            return (
              <G key={i}>
                <Line x1={PL} y1={gy} x2={width - PR} y2={gy} stroke="#EEF2F7" strokeWidth={1} />
                <SvgText x={PL - 6} y={gy + 3} fontSize={9} fill="#9CA3AF" textAnchor="end">{yFormat(max * g)}</SvgText>
              </G>
            );
          })}
          {data.map((d, i) => {
            const h = (d.value / max) * innerH;
            return <Rect key={i} x={cxOf(i) - bw / 2} y={PT + innerH - h} width={bw} height={h} rx={3} fill={color} fillOpacity={hv === null || hv === i ? 1 : 0.5} />;
          })}
          {xTicks.map((i, k) => (
            <SvgText key={k} x={cxOf(i)} y={height - 8} fontSize={9} fill="#9CA3AF" textAnchor="middle">
              {xFormat(data[i]?.label ?? "")}
            </SvgText>
          ))}
        </Svg>
      ) : null}
      {hv !== null ? (
        <View pointerEvents="none" style={[styles.tip, { left: Math.max(2, Math.min(width - 124, cxOf(hv) - 60)) }]}>
          <Text style={styles.tipLabel}>{xFormat(data[hv].label)}</Text>
          <Text style={styles.tipValue}>{valueFormat(data[hv].value)}</Text>
        </View>
      ) : null}
    </View>
  );
}

// --- HBarChart horizontal (répartitions / classements, en Views) -------------
export function HBarChart({
  data,
  max,
  valueFormat = formatInt,
}: {
  data: { label: string; value: number; color?: string }[];
  max?: number;
  valueFormat?: (n: number) => string;
}) {
  const m = Math.max(1, max ?? Math.max(...data.map((d) => d.value), 1));
  return (
    <View style={{ gap: 8 }}>
      {data.map((d, i) => (
        <View key={i} style={styles.hbarRow}>
          <Text style={styles.hbarLabel} numberOfLines={1}>{d.label}</Text>
          <View style={styles.hbarTrack}>
            <View style={[styles.hbarFill, { width: `${(d.value / m) * 100}%`, backgroundColor: d.color ?? PALETTE[i % PALETTE.length] }]} />
          </View>
          <Text style={styles.hbarValue}>{valueFormat(d.value)}</Text>
        </View>
      ))}
      {data.length === 0 ? <Text style={styles.empty}>Aucune donnée</Text> : null}
    </View>
  );
}

// --- Donut (+ légende) -------------------------------------------------------
export function Donut({
  data,
  size = 150,
  thickness = 22,
  centerLabel,
  centerValue,
  valueFormat = formatInt,
}: {
  data: { label: string; value: number; color?: string }[];
  size?: number;
  thickness?: number;
  centerLabel?: string;
  centerValue?: string;
  valueFormat?: (n: number) => string;
}) {
  const total = data.reduce((s, d) => s + d.value, 0);
  const r = (size - thickness) / 2;
  const c = 2 * Math.PI * r;
  let acc = 0;
  const [active, setActive] = useState<number | null>(null);
  const av = active !== null && active >= 0 && active < data.length ? active : null;
  const centerV = av !== null ? valueFormat(data[av].value) : centerValue;
  const centerL = av !== null && total > 0 ? `${Math.round((data[av].value / total) * 100)}% · ${data[av].label}` : centerLabel;
  return (
    <View style={styles.donutWrap}>
      <View style={{ width: size, height: size }}>
        <Svg width={size} height={size}>
          <G rotation={-90} originX={size / 2} originY={size / 2}>
            <Circle cx={size / 2} cy={size / 2} r={r} stroke="#EEF2F7" strokeWidth={thickness} fill="none" />
            {total > 0 &&
              data.map((d, i) => {
                const frac = d.value / total;
                const dash = frac * c;
                const el = (
                  <Circle
                    key={i}
                    cx={size / 2}
                    cy={size / 2}
                    r={r}
                    stroke={d.color ?? PALETTE[i % PALETTE.length]}
                    strokeWidth={av === i ? thickness + 5 : thickness}
                    fill="none"
                    strokeDasharray={`${dash} ${c - dash}`}
                    strokeDashoffset={-acc * c}
                    opacity={av === null || av === i ? 1 : 0.45}
                  />
                );
                acc += frac;
                return el;
              })}
          </G>
        </Svg>
        {(centerV || centerL) ? (
          <View style={styles.donutCenter} pointerEvents="none">
            {centerV ? <Text style={styles.donutCenterVal}>{centerV}</Text> : null}
            {centerL ? <Text style={styles.donutCenterLab} numberOfLines={1}>{centerL}</Text> : null}
          </View>
        ) : null}
      </View>
      <View style={styles.legend}>
        {data.map((d, i) => (
          <Pressable
            key={i}
            style={styles.legendRow}
            onHoverIn={() => setActive(i)}
            onHoverOut={() => setActive(null)}
            onPress={() => setActive((p) => (p === i ? null : i))}
          >
            <View style={[styles.legendDot, { backgroundColor: d.color ?? PALETTE[i % PALETTE.length] }]} />
            <Text style={styles.legendLabel} numberOfLines={1}>{d.label}</Text>
            <Text style={styles.legendValue}>{valueFormat(d.value)}</Text>
          </Pressable>
        ))}
        {total === 0 ? <Text style={styles.empty}>Aucune donnée</Text> : null}
      </View>
    </View>
  );
}

