import React from "react";
import { Pressable, ScrollView, StyleSheet, Text, View } from "react-native";
import * as Updates from "expo-updates";
import { supabase } from "@/services/supabase";
import { Pastel } from "@/constants/pastel";
import { Font } from "@/constants/typography";

type Props = { children: React.ReactNode };
type State = { hasError: boolean; message: string };

// Filet de sécurité global : capture les erreurs de RENDU JS (pas les crashs natifs)
// pour éviter que l'app se ferme silencieusement, affiche le message (diagnostic) et
// propose de se déconnecter — ce qui casse toute boucle de crash liée à une session
// persistée.
export default class ErrorBoundary extends React.Component<Props, State> {
  state: State = { hasError: false, message: "" };

  static getDerivedStateFromError(error: any): State {
    return { hasError: true, message: String(error?.message ?? error) };
  }

  componentDidCatch(error: any, info: any) {
    console.error("[ErrorBoundary]", error, info?.componentStack);
  }

  private reload = async () => {
    try {
      await Updates.reloadAsync();
    } catch {
      this.setState({ hasError: false, message: "" });
    }
  };

  private signOut = async () => {
    try {
      await supabase.auth.signOut();
    } catch {
      /* ignore */
    }
    try {
      await Updates.reloadAsync();
    } catch {
      this.setState({ hasError: false, message: "" });
    }
  };

  render() {
    if (!this.state.hasError) return this.props.children;
    return (
      <View style={styles.root}>
        <Text style={styles.title}>Oups, un souci est survenu</Text>
        <Text style={styles.sub}>
          Tu peux réessayer. Si le problème persiste, déconnecte-toi puis reconnecte-toi.
        </Text>
        <ScrollView style={styles.errBox} contentContainerStyle={styles.errInner}>
          <Text style={styles.errText}>{this.state.message}</Text>
        </ScrollView>
        <Pressable style={styles.btn} onPress={this.reload}>
          <Text style={styles.btnText}>Réessayer</Text>
        </Pressable>
        <Pressable style={[styles.btn, styles.btnAlt]} onPress={this.signOut}>
          <Text style={[styles.btnText, styles.btnAltText]}>Se déconnecter</Text>
        </Pressable>
      </View>
    );
  }
}

const styles = StyleSheet.create({
  root: {
    flex: 1,
    backgroundColor: Pastel.primary,
    alignItems: "center",
    justifyContent: "center",
    padding: 28,
    gap: 16,
  },
  title: {
    color: "#FFFFFF",
    fontSize: 22,
    fontFamily: Font.extraBold,
    textAlign: "center",
    includeFontPadding: false,
  },
  sub: {
    color: "rgba(255,255,255,0.75)",
    fontSize: 14,
    lineHeight: 20,
    fontFamily: Font.regular,
    textAlign: "center",
    includeFontPadding: false,
  },
  errBox: {
    maxHeight: 140,
    alignSelf: "stretch",
    backgroundColor: "rgba(0,0,0,0.25)",
    borderRadius: 12,
  },
  errInner: { padding: 12 },
  errText: {
    color: "rgba(255,255,255,0.6)",
    fontSize: 12,
    fontFamily: Font.regular,
  },
  btn: {
    alignSelf: "stretch",
    backgroundColor: Pastel.teal,
    paddingVertical: 16,
    borderRadius: 14,
    alignItems: "center",
  },
  btnText: {
    color: "#FFFFFF",
    fontSize: 16,
    fontFamily: Font.extraBold,
    includeFontPadding: false,
  },
  btnAlt: {
    backgroundColor: "transparent",
    paddingVertical: 10,
  },
  btnAltText: { color: "rgba(255,255,255,0.7)", fontSize: 14, fontFamily: Font.semiBold },
});
