import { ReactNode, useMemo, useState } from "react";
import { Pressable, ScrollView, StyleSheet, Text, TextInput, View } from "react-native";
import { Pastel } from "@/constants/pastel";
import { Font } from "@/constants/typography";

export type Column<T> = {
  key: string;
  label: string;
  width?: number;
  align?: "left" | "right";
  render?: (row: T) => ReactNode;
  sortValue?: (row: T) => string | number;
};

export function DataTable<T>({
  columns,
  rows,
  pageSize = 20,
  emptyText = "Aucune donnée",
  searchKeys,
  searchPlaceholder = "Rechercher…",
}: {
  columns: Column<T>[];
  rows: T[];
  pageSize?: number;
  emptyText?: string;
  searchKeys?: ((r: T) => string)[];
  searchPlaceholder?: string;
}) {
  const [sortKey, setSortKey] = useState<string | null>(null);
  const [asc, setAsc] = useState(false);
  const [page, setPage] = useState(0);
  const [query, setQuery] = useState("");

  const filtered = useMemo(() => {
    if (!searchKeys?.length || !query.trim()) return rows;
    const q = query.trim().toLowerCase();
    return rows.filter((r) => searchKeys.some((fn) => (fn(r) ?? "").toLowerCase().includes(q)));
  }, [rows, query, searchKeys]);

  const sorted = useMemo(() => {
    if (!sortKey) return filtered;
    const col = columns.find((c) => c.key === sortKey);
    if (!col?.sortValue) return filtered;
    const copy = [...filtered];
    copy.sort((a, b) => {
      const va = col.sortValue!(a);
      const vb = col.sortValue!(b);
      if (va < vb) return asc ? -1 : 1;
      if (va > vb) return asc ? 1 : -1;
      return 0;
    });
    return copy;
  }, [filtered, sortKey, asc, columns]);

  const pageCount = Math.max(1, Math.ceil(sorted.length / pageSize));
  const safePage = Math.min(page, pageCount - 1);
  const visible = sorted.slice(safePage * pageSize, safePage * pageSize + pageSize);
  const totalWidth = columns.reduce((s, c) => s + (c.width ?? 120), 0);

  const toggleSort = (key: string) => {
    if (sortKey === key) setAsc((v) => !v);
    else {
      setSortKey(key);
      setAsc(false);
    }
    setPage(0);
  };

  return (
    <View style={{ gap: 10 }}>
      {searchKeys?.length ? (
        <View style={styles.searchRow}>
          <TextInput
            value={query}
            onChangeText={(v) => { setQuery(v); setPage(0); }}
            placeholder={searchPlaceholder}
            placeholderTextColor="#9CA3AF"
            style={styles.searchInput}
            autoCapitalize="none"
          />
          {query ? <Text style={styles.searchCount}>{sorted.length} résultat{sorted.length > 1 ? "s" : ""}</Text> : null}
        </View>
      ) : null}
      <ScrollView horizontal showsHorizontalScrollIndicator={false}>
        <View style={{ minWidth: totalWidth }}>
          <View style={styles.headRow}>
            {columns.map((c) => (
              <Pressable
                key={c.key}
                onPress={() => c.sortValue && toggleSort(c.key)}
                style={[styles.cell, { width: c.width ?? 120 }, c.align === "right" && styles.right]}
              >
                <Text style={styles.headTxt} numberOfLines={1}>
                  {c.label}
                  {sortKey === c.key ? (asc ? " ▲" : " ▼") : ""}
                </Text>
              </Pressable>
            ))}
          </View>
          {visible.map((row, i) => (
            <View key={i} style={[styles.row, i % 2 === 1 && styles.rowAlt]}>
              {columns.map((c) => (
                <View key={c.key} style={[styles.cell, { width: c.width ?? 120 }, c.align === "right" && styles.right]}>
                  {c.render ? (
                    c.render(row)
                  ) : (
                    <Text style={styles.cellTxt} numberOfLines={1}>
                      {String((row as any)[c.key] ?? "—")}
                    </Text>
                  )}
                </View>
              ))}
            </View>
          ))}
          {visible.length === 0 ? <Text style={styles.empty}>{emptyText}</Text> : null}
        </View>
      </ScrollView>

      {pageCount > 1 ? (
        <View style={styles.pager}>
          <Pressable onPress={() => setPage((p) => Math.max(0, p - 1))} disabled={safePage === 0} style={[styles.pageBtn, safePage === 0 && styles.pageBtnOff]}>
            <Text style={styles.pageBtnTxt}>‹ Préc.</Text>
          </Pressable>
          <Text style={styles.pageInfo}>{safePage + 1} / {pageCount}</Text>
          <Pressable onPress={() => setPage((p) => Math.min(pageCount - 1, p + 1))} disabled={safePage >= pageCount - 1} style={[styles.pageBtn, safePage >= pageCount - 1 && styles.pageBtnOff]}>
            <Text style={styles.pageBtnTxt}>Suiv. ›</Text>
          </Pressable>
        </View>
      ) : null}
    </View>
  );
}

const styles = StyleSheet.create({
  headRow: { flexDirection: "row", borderBottomWidth: 2, borderBottomColor: "#EEF2F7", backgroundColor: "#F8FAFF" },
  row: { flexDirection: "row", borderBottomWidth: 1, borderBottomColor: "#F1F5F9" },
  rowAlt: { backgroundColor: "#FBFCFE" },
  cell: { paddingHorizontal: 12, paddingVertical: 11, justifyContent: "center" },
  right: { alignItems: "flex-end" },
  headTxt: { color: "#6B7280", fontSize: 11, fontFamily: Font.extraBold, textTransform: "uppercase", letterSpacing: 0.4, includeFontPadding: false },
  cellTxt: { color: "#242D41", fontSize: 13, fontFamily: Font.semiBold, includeFontPadding: false },
  empty: { color: "#9CA3AF", fontSize: 13, fontStyle: "italic", padding: 16 },
  pager: { flexDirection: "row", alignItems: "center", justifyContent: "center", gap: 14 },
  pageBtn: { backgroundColor: "#FFFFFF", borderWidth: 1, borderColor: "#E5E7EB", borderRadius: 9, paddingHorizontal: 14, paddingVertical: 7 },
  pageBtnOff: { opacity: 0.4 },
  pageBtnTxt: { color: Pastel.primary, fontSize: 13, fontFamily: Font.bold, includeFontPadding: false },
  pageInfo: { color: "#6B7280", fontSize: 13, fontFamily: Font.semiBold, includeFontPadding: false },
  searchRow: { flexDirection: "row", alignItems: "center", gap: 12, flexWrap: "wrap" },
  searchInput: { flex: 1, minWidth: 200, backgroundColor: "#F3F4F6", borderWidth: 1, borderColor: "#E5E7EB", borderRadius: 10, paddingHorizontal: 12, paddingVertical: 9, fontSize: 14, color: "#242D41", includeFontPadding: false },
  searchCount: { color: "#6B7280", fontSize: 13, fontFamily: Font.semiBold, includeFontPadding: false },
});
