import { useCallback, useEffect, useState } from "react";
import { Pressable, StyleSheet, Text, View } from "react-native";
import JovialAdminShell from "@/components/ui/JovialAdminShell";
import PeriodFilter, { DEFAULT_PERIOD, Period } from "@/components/ui/PeriodFilter";
import { ChartCard, HBarChart } from "@/components/ui/charts";
import { Pastel } from "@/constants/pastel";
import { Font } from "@/constants/typography";
import {
  getTopEstablishments,
  getUsersByRegion,
  type TopEstablishment,
  type TopMetric,
  type LabelCount,
} from "@/services/admin";

const METRICS: { key: TopMetric; label: string }[] = [
  { key: "reservations", label: "Réservations" },
  { key: "events", label: "Événements" },
  { key: "club_activity", label: "Activité club" },
  { key: "favorites", label: "Favoris" },
];

export default function AdminLeaderboards() {
  const [period, setPeriod] = useState<Period>(DEFAULT_PERIOD);
  const [metric, setMetric] = useState<TopMetric>("reservations");
  const [loading, setLoading] = useState(true);
  const [err, setErr] = useState<string | null>(null);
  const [top, setTop] = useState<TopEstablishment[]>([]);
  const [zones, setZones] = useState<LabelCount[]>([]);

  const load = useCallback(async () => {
    setLoading(true);
    setErr(null);
    try {
      const range = { from: period.from, to: period.to };
      const [t, z] = await Promise.all([
        getTopEstablishments(range, metric, 15),
        getUsersByRegion(),
      ]);
      setTop(t); setZones(z);
    } catch (e: any) {
      setErr(e?.message ?? "Erreur de chargement");
    } finally {
      setLoading(false);
    }
  }, [period, metric]);

  useEffect(() => { load(); }, [load]);

  return (
    <JovialAdminShell title="Classements" subtitle={period.label} loading={loading} onRefresh={load}>
      <PeriodFilter value={period} onChange={setPeriod} />
      {err ? <Text style={styles.err}>{err}</Text> : null}

      <ChartCard
        title="Top établissements"
        subtitle="Classés sur la période sélectionnée"
        right={
          <View style={styles.metrics}>
            {METRICS.map((m) => {
              const on = metric === m.key;
              return (
                <Pressable key={m.key} onPress={() => setMetric(m.key)} style={[styles.metricBtn, on && styles.metricBtnOn]}>
                  <Text style={[styles.metricTxt, on && styles.metricTxtOn]}>{m.label}</Text>
                </Pressable>
              );
            })}
          </View>
        }
      >
        <HBarChart data={top.map((t) => ({ label: t.name ?? `#${t.venue_id}`, value: t.metric_value, color: Pastel.primary }))} />
      </ChartCard>

      <ChartCard title="Top régions" subtitle="Par nombre d'utilisateurs">
        <HBarChart data={zones.slice(0, 12).map((z) => ({ label: z.label, value: z.count, color: Pastel.teal }))} />
      </ChartCard>
    </JovialAdminShell>
  );
}

const styles = StyleSheet.create({
  err: { color: "#DC2626", fontSize: 13, fontFamily: Font.semiBold },
  metrics: { flexDirection: "row", gap: 6, flexWrap: "wrap" },
  metricBtn: { paddingHorizontal: 11, paddingVertical: 6, borderRadius: 8, backgroundColor: "#F3F4F6" },
  metricBtnOn: { backgroundColor: Pastel.primary },
  metricTxt: { color: "#6B7280", fontSize: 12, fontFamily: Font.bold, includeFontPadding: false },
  metricTxtOn: { color: "#FFFFFF" },
});
