import { StyleSheet, Text, View } from "react-native";
import { Ionicons } from "@expo/vector-icons";

import { PLAN_CAPABILITIES, type PlanCapabilities, type PlanCode } from "@/utils/planFeatureGate";
import { Pastel } from "@/constants/pastel";
import { Font } from "@/constants/typography";

const PLANS: { code: PlanCode; label: string }[] = [
  { code: "visibilite", label: "Visibilité" },
  { code: "rayonnement", label: "Rayonnement" },
  { code: "pro", label: "Pro" },
];

type Row = { label: string; get?: (c: PlanCapabilities) => string; bool?: (c: PlanCapabilities) => boolean };

const ROWS: Row[] = [
  { label: "Tags du lieu", get: (c) => String(c.tagsLimit) },
  { label: "Événements / an", get: (c) => (c.eventQuota === null ? "Illimité" : String(c.eventQuota)) },
  { label: "Rappels aux abonnés", bool: (c) => c.hasReminders },
  { label: "Club Jovial", bool: (c) => c.hasClubJovial },
  { label: "Coups de projecteur / an", get: (c) => (c.spotlightQuota === 0 ? "—" : String(c.spotlightQuota)) },
  { label: "Sélection Jovial / an", get: (c) => (c.carouselBoostQuota === 0 ? "—" : String(c.carouselBoostQuota)) },
  { label: "Notification ciblée / an", get: (c) => (c.targetedNotificationQuota === 0 ? "—" : String(c.targetedNotificationQuota)) },
  { label: "Statistiques avancées", bool: (c) => c.hasAnalytics },
];

export function FeatureComparison() {
  return (
    <View style={styles.wrap}>
      <Text style={styles.title}>Comparer les offres</Text>
      <View style={styles.table}>
        <View style={[styles.row, styles.headerRow]}>
          <View style={styles.featureCell} />
          {PLANS.map((p) => (
            <View key={p.code} style={styles.planCell}>
              <Text style={styles.planLabel} numberOfLines={1}>{p.label}</Text>
            </View>
          ))}
        </View>

        {ROWS.map((r, idx) => (
          <View key={r.label} style={[styles.row, idx % 2 === 1 && styles.rowAlt]}>
            <View style={styles.featureCell}>
              <Text style={styles.featureLabel}>{r.label}</Text>
            </View>
            {PLANS.map((p) => {
              const caps = PLAN_CAPABILITIES[p.code];
              return (
                <View key={p.code} style={styles.planCell}>
                  {r.bool ? (
                    r.bool(caps) ? (
                      <Ionicons name="checkmark-circle" size={18} color={Pastel.teal} />
                    ) : (
                      <Text style={styles.dash}>—</Text>
                    )
                  ) : (
                    <Text style={styles.value}>{r.get!(caps)}</Text>
                  )}
                </View>
              );
            })}
          </View>
        ))}
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  wrap: { width: "100%", maxWidth: 760, alignSelf: "center", marginTop: 28, paddingHorizontal: 4 },
  title: { fontSize: 18, fontFamily: Font.extraBold, color: Pastel.text, textAlign: "center", marginBottom: 14, includeFontPadding: false },
  table: { borderWidth: 1, borderColor: Pastel.border, borderRadius: 16, overflow: "hidden", backgroundColor: Pastel.surface },
  row: { flexDirection: "row", alignItems: "center", minHeight: 44 },
  headerRow: { backgroundColor: Pastel.surfaceAlt, borderBottomWidth: 1, borderBottomColor: Pastel.border },
  rowAlt: { backgroundColor: Pastel.surfaceAlt },
  featureCell: { flex: 1.5, paddingHorizontal: 14, paddingVertical: 10, justifyContent: "center" },
  planCell: { flex: 1, alignItems: "center", justifyContent: "center", paddingVertical: 10 },
  featureLabel: { fontSize: 13, fontFamily: Font.semiBold, color: Pastel.text, includeFontPadding: false },
  planLabel: { fontSize: 13, fontFamily: Font.extraBold, color: Pastel.primary, includeFontPadding: false },
  value: { fontSize: 14, fontFamily: Font.bold, color: Pastel.text, includeFontPadding: false },
  dash: { fontSize: 14, color: Pastel.textMuted, includeFontPadding: false },
});
