import { useCallback, useEffect, useMemo, useState } from "react";
import {
  ActivityIndicator,
  Image,
  KeyboardAvoidingView,
  Modal,
  Platform,
  Pressable,
  ScrollView,
  StyleSheet,
  Text,
  TextInput,
  View,
} from "react-native";
import { useLocalSearchParams, useRouter } from "expo-router";
import { Ionicons } from "@expo/vector-icons";
import { useSafeAreaInsets } from "react-native-safe-area-context";

import { useAuth } from "@/providers/AuthProvider";
import { supabase } from "@/services/supabase";
import { Pastel } from "@/constants/pastel";
import { Font } from "@/constants/typography";
import { UserAvatar } from "@/components/ui/UserAvatar";
import { SharedEntityCard } from "@/components/ui/SharedEntityCard";
import { MentionText } from "@/components/ui/MentionText";
import { loadSharedCardMap, sharedCardKey, type SharedCard } from "@/services/sharedCards";

type Profile = { user_id: string; firstname: string | null; lastname: string | null; handle: string | null; avatar_url: string | null };
type Comment = { id: number; author_id: string | null; body: string; created_at: string; author?: Profile | null };
type Post = { id: number; author_id: string | null; body: string | null; created_at: string; venue_id: number | null; event_id: number | null };

const displayName = (p?: Profile | null) => p?.firstname?.trim() || p?.handle?.trim() || "Membre";

function timeAgo(dateStr: string): string {
  const diff = Math.floor((Date.now() - new Date(dateStr).getTime()) / 1000);
  if (diff < 60) return "À l'instant";
  if (diff < 3600) return `${Math.floor(diff / 60)} min`;
  if (diff < 86400) return `${Math.floor(diff / 3600)} h`;
  if (diff < 604800) return `${Math.floor(diff / 86400)} j`;
  return new Date(dateStr).toLocaleDateString("fr-FR");
}

export default function ProfilePostDetailScreen() {
  const router = useRouter();
  const insets = useSafeAreaInsets();
  const { postId } = useLocalSearchParams<{ postId?: string }>();
  const id = Number(postId ?? 0);
  const { session } = useAuth();
  const userId = session?.user?.id ?? null;

  const [loading, setLoading] = useState(true);
  const [post, setPost] = useState<Post | null>(null);
  const [author, setAuthor] = useState<Profile | null>(null);
  const [media, setMedia] = useState<string[]>([]);
  const [card, setCard] = useState<SharedCard | null>(null);
  const [likeCount, setLikeCount] = useState(0);
  const [liked, setLiked] = useState(false);
  const [saved, setSaved] = useState(false);
  const [comments, setComments] = useState<Comment[]>([]);
  const [draft, setDraft] = useState("");
  const [sending, setSending] = useState(false);
  const [viewerUri, setViewerUri] = useState<string | null>(null);
  // Amis (pour @identification en commentaire).
  const [friends, setFriends] = useState<{ user_id: string; handle: string | null; firstname: string | null; avatar_url: string | null }[]>([]);

  useEffect(() => {
    if (!userId) return;
    let cancelled = false;
    (async () => {
      const [{ data: following }, { data: followers }] = await Promise.all([
        supabase.from("user_follows").select("following_id").eq("follower_id", userId),
        supabase.from("user_follows").select("follower_id").eq("following_id", userId),
      ]);
      const ids = Array.from(new Set([
        ...((following ?? []).map((r: any) => String(r.following_id ?? ""))),
        ...((followers ?? []).map((r: any) => String(r.follower_id ?? ""))),
      ])).filter(Boolean);
      if (ids.length === 0) return;
      const { data } = await supabase.from("profiles").select("user_id, handle, firstname, avatar_url").in("user_id", ids);
      if (!cancelled) setFriends(((data as any[]) ?? []).filter((f) => !!f?.user_id));
    })();
    return () => { cancelled = true; };
  }, [userId]);

  const mentionQuery = useMemo(() => {
    const m = draft.match(/@([a-zA-Z0-9_.-]*)$/);
    return m ? m[1].toLowerCase() : null;
  }, [draft]);
  const mentionSuggestions = useMemo(() => {
    if (mentionQuery === null) return [];
    return friends
      .filter((f) => (f.handle ?? "").toLowerCase().startsWith(mentionQuery) || (f.firstname ?? "").toLowerCase().startsWith(mentionQuery))
      .slice(0, 5);
  }, [mentionQuery, friends]);
  const selectMention = (f: { handle: string | null }) => {
    if (!f.handle) return;
    setDraft((prev) => prev.replace(/@([a-zA-Z0-9_.-]*)$/, `@${f.handle} `));
  };

  const load = useCallback(async () => {
    if (!id) return;
    setLoading(true);
    const { data: p } = await supabase
      .from("profile_posts")
      .select("id, author_id, body, created_at, venue_id, event_id")
      .eq("id", id)
      .maybeSingle();
    if (!p) { setLoading(false); return; }
    const postRow = p as Post;
    setPost(postRow);

    const [{ data: mediaRows }, { data: likeRows }, { data: saveRows }, { data: commentRows }] = await Promise.all([
      supabase.from("profile_post_media").select("url").eq("post_id", id).order("created_at", { ascending: true }),
      supabase.from("profile_post_likes").select("user_id").eq("post_id", id),
      userId
        ? supabase.from("profile_post_saves").select("post_id").eq("post_id", id).eq("user_id", userId)
        : Promise.resolve({ data: [] as any[] }),
      supabase.from("profile_post_comments").select("id, author_id, body, created_at").eq("post_id", id).order("created_at", { ascending: true }),
    ]);

    setMedia(((mediaRows as any[]) ?? []).map((r) => r.url));
    const likes = (likeRows as any[]) ?? [];
    setLikeCount(likes.length);
    setLiked(!!userId && likes.some((l) => l.user_id === userId));
    setSaved((((saveRows as any[]) ?? []).length) > 0);

    const cmts = (commentRows as { id: number; author_id: string | null; body: string; created_at: string }[]) ?? [];
    const ids = Array.from(new Set([
      ...(postRow.author_id ? [postRow.author_id] : []),
      ...cmts.map((c) => c.author_id).filter(Boolean) as string[],
    ]));
    const { data: profs } = ids.length
      ? await supabase.from("profiles").select("user_id, firstname, lastname, handle, avatar_url").in("user_id", ids)
      : { data: [] as Profile[] };
    const pmap = new Map(((profs as Profile[]) ?? []).map((pr) => [pr.user_id, pr]));
    setAuthor(postRow.author_id ? pmap.get(postRow.author_id) ?? null : null);
    setComments(cmts.map((c) => ({ ...c, author: c.author_id ? pmap.get(c.author_id) ?? null : null })));

    const cardMap = await loadSharedCardMap([postRow]);
    const ck = sharedCardKey(postRow);
    setCard(ck ? cardMap[ck] ?? null : null);
    setLoading(false);
  }, [id, userId]);

  useEffect(() => { load(); }, [load]);

  const toggleLike = async () => {
    if (!userId) return;
    if (liked) {
      setLiked(false); setLikeCount((c) => Math.max(0, c - 1));
      await supabase.from("profile_post_likes").delete().eq("post_id", id).eq("user_id", userId);
    } else {
      setLiked(true); setLikeCount((c) => c + 1);
      await supabase.from("profile_post_likes").insert({ post_id: id, user_id: userId });
    }
  };
  const toggleSave = async () => {
    if (!userId) return;
    if (saved) {
      setSaved(false);
      await supabase.from("profile_post_saves").delete().eq("post_id", id).eq("user_id", userId);
    } else {
      setSaved(true);
      await supabase.from("profile_post_saves").upsert({ post_id: id, user_id: userId }, { onConflict: "post_id,user_id" });
    }
  };
  const sendComment = async () => {
    const body = draft.trim();
    if (!body || !userId || sending) return;
    setSending(true);
    const { error } = await supabase.from("profile_post_comments").insert({ post_id: id, author_id: userId, body });
    setSending(false);
    if (!error) {
      setDraft("");
      // Notifier les amis identifiés (@) dans le commentaire : notif in-app + push.
      const handles = (body.match(/@([a-zA-Z0-9_.-]{2,30})/g) ?? []).map((m) => m.slice(1).toLowerCase());
      if (handles.length > 0) {
        const mentionUserIds = friends
          .filter((f) => f.handle && handles.includes(f.handle.toLowerCase()))
          .map((f) => f.user_id);
        if (mentionUserIds.length > 0) {
          supabase.functions
            .invoke("profile-post-notify", { body: { post_id: id, author_id: userId, body, mention_user_ids: mentionUserIds } })
            .catch(() => {});
        }
      }
      load();
    }
  };

  return (
    <View style={styles.screen}>
      <View style={[styles.header, { paddingTop: insets.top > 0 ? insets.top + 4 : 14 }]}>
        <Pressable style={styles.backBtn} onPress={() => router.back()} hitSlop={10}>
          <Ionicons name="chevron-back" size={22} color={Pastel.text} />
        </Pressable>
        <Text style={styles.headerTitle}>Publication</Text>
        <View style={{ width: 36 }} />
      </View>

      {loading ? (
        <View style={styles.centered}><ActivityIndicator color={Pastel.primary} /></View>
      ) : !post ? (
        <View style={styles.centered}><Text style={styles.muted}>Publication introuvable.</Text></View>
      ) : (
        <KeyboardAvoidingView style={{ flex: 1 }} behavior={Platform.OS === "ios" ? "padding" : undefined} keyboardVerticalOffset={insets.top + 44}>
          <ScrollView contentContainerStyle={styles.content} keyboardShouldPersistTaps="handled">
            {/* Auteur */}
            <Pressable
              style={styles.authorRow}
              onPress={() => post.author_id && router.push(`/profile/${post.author_id}` as any)}
            >
              <UserAvatar uri={author?.avatar_url} name={displayName(author)} seed={post.author_id ?? "?"} size={42} />
              <View style={{ flex: 1 }}>
                <Text style={styles.authorName}>{displayName(author)}</Text>
                <Text style={styles.postTime}>{timeAgo(post.created_at)}</Text>
              </View>
            </Pressable>

            {post.body ? <MentionText style={styles.body}>{post.body}</MentionText> : null}

            {card ? <SharedEntityCard card={card} style={{ marginTop: 10 }} /> : null}

            {media.length > 0 ? (
              <View style={styles.mediaWrap}>
                {media.map((url, i) => (
                  <Pressable key={`${url}-${i}`} onPress={() => setViewerUri(url)}>
                    <Image source={{ uri: url }} style={styles.media} resizeMode="cover" />
                  </Pressable>
                ))}
              </View>
            ) : null}

            {/* Actions */}
            <View style={styles.actions}>
              <Pressable style={styles.actionBtn} onPress={toggleLike}>
                <Ionicons name={liked ? "heart" : "heart-outline"} size={22} color={liked ? "#EF4444" : Pastel.textMuted} />
                <Text style={[styles.actionText, liked ? { color: "#EF4444" } : null]}>{likeCount > 0 ? likeCount : "J'aime"}</Text>
              </Pressable>
              <Pressable style={styles.actionBtn} onPress={toggleSave}>
                <Ionicons name={saved ? "bookmark" : "bookmark-outline"} size={20} color={saved ? "#F97316" : Pastel.textMuted} />
                <Text style={[styles.actionText, saved ? { color: "#F97316" } : null]}>{saved ? "Sauvegardé" : "Sauvegarder"}</Text>
              </Pressable>
            </View>

            <View style={styles.divider} />

            {/* Commentaires */}
            <Text style={styles.commentsTitle}>
              {comments.length > 0 ? `${comments.length} commentaire${comments.length > 1 ? "s" : ""}` : "Commentaires"}
            </Text>
            {comments.length === 0 ? (
              <View style={styles.commentEmpty}>
                <Text style={styles.commentEmptyEmoji}>💬</Text>
                <Text style={styles.muted}>Sois le premier à réagir !</Text>
              </View>
            ) : (
              comments.map((c) => (
                <Pressable
                  key={c.id}
                  style={styles.commentRow}
                  onPress={() => c.author_id && router.push(`/profile/${c.author_id}` as any)}
                >
                  <UserAvatar uri={c.author?.avatar_url} name={displayName(c.author)} seed={c.author_id ?? "?"} size={34} />
                  <View style={styles.commentBubble}>
                    <Text style={styles.commentAuthor}>{displayName(c.author)} <Text style={styles.commentTime}>· {timeAgo(c.created_at)}</Text></Text>
                    <MentionText style={styles.commentBody}>{c.body}</MentionText>
                  </View>
                </Pressable>
              ))
            )}
          </ScrollView>

          {/* @autocomplétion amis */}
          {mentionSuggestions.length > 0 ? (
            <View style={styles.mentionBox}>
              {mentionSuggestions.map((f) => (
                <Pressable key={f.user_id} style={styles.mentionRow} onPress={() => selectMention(f)}>
                  <UserAvatar uri={f.avatar_url} name={f.firstname ?? f.handle} seed={f.user_id} size={28} />
                  <Text style={styles.mentionName} numberOfLines={1}>
                    {f.firstname?.trim() || f.handle}{f.handle ? ` · @${f.handle}` : ""}
                  </Text>
                </Pressable>
              ))}
            </View>
          ) : null}

          {/* Composer commentaire */}
          <View style={[styles.composer, { paddingBottom: insets.bottom > 0 ? insets.bottom : 12 }]}>
            <TextInput
              value={draft}
              onChangeText={setDraft}
              placeholder="Ajoute un commentaire…"
              placeholderTextColor="#9CA3AF"
              style={styles.composerInput}
              multiline
              maxLength={300}
            />
            <Pressable
              style={[styles.sendBtn, !draft.trim() || sending ? styles.sendBtnDisabled : null]}
              onPress={sendComment}
              disabled={!draft.trim() || sending}
            >
              <Ionicons name="send" size={16} color="#FFFFFF" />
            </Pressable>
          </View>
        </KeyboardAvoidingView>
      )}

      {/* Viewer image plein écran */}
      <Modal visible={!!viewerUri} transparent animationType="fade" onRequestClose={() => setViewerUri(null)}>
        <Pressable style={styles.viewerBackdrop} onPress={() => setViewerUri(null)}>
          {viewerUri ? <Image source={{ uri: viewerUri }} style={styles.viewerBlur} resizeMode="cover" blurRadius={18} /> : null}
          <View style={styles.viewerOverlay} />
          <Pressable style={styles.viewerClose} onPress={() => setViewerUri(null)}>
            <Ionicons name="close" size={22} color="#fff" />
          </Pressable>
          {viewerUri ? (
            <View style={styles.viewerImageWrap}>
              <Image source={{ uri: viewerUri }} style={styles.viewerImage} resizeMode="contain" />
            </View>
          ) : null}
        </Pressable>
      </Modal>
    </View>
  );
}

