import { useCallback, useEffect, useState } from "react";
import { StyleSheet, Text, View } from "react-native";
import JovialAdminShell from "@/components/ui/JovialAdminShell";
import PeriodFilter, { DEFAULT_PERIOD, Period } from "@/components/ui/PeriodFilter";
import { ChartCard, KPIStat, LineChart, Donut, HBarChart, formatEuros, formatInt, formatCompact, PALETTE } from "@/components/ui/charts";
import { InfoHint } from "@/components/ui/InfoHint";
import { ExportCsvButton } from "@/components/ui/ExportCsvButton";
import { type CsvColumn } from "@/utils/csv";
import { Pastel } from "@/constants/pastel";
import { Font } from "@/constants/typography";
import {
  getRevenueSummary,
  getRevenueTimeseries,
  getSubscriptionsByPlan,
  getUserRevenue,
  type RevenueSummary,
  type TimePoint,
  type LabelCount,
  type UserRevenue,
} from "@/services/admin";

const eurosCsv = (cents: number | null | undefined) => ((cents ?? 0) / 100).toFixed(2).replace(".", ",");
const REV_TS_CSV_COLUMNS: CsvColumn<TimePoint>[] = [
  { label: "Période", value: (r) => r.bucket },
  { label: "MRR (€)", value: (r) => eurosCsv(r.mrr_cents) },
];
const REV_PLAN_CSV_COLUMNS: CsvColumn<LabelCount>[] = [
  { label: "Plan", value: (r) => r.label },
  { label: "Abonnements", value: (r) => r.count },
  { label: "MRR (€)", value: (r) => eurosCsv(r.mrr_cents) },
];

export default function AdminRevenue() {
  const [period, setPeriod] = useState<Period>(DEFAULT_PERIOD);
  const [loading, setLoading] = useState(true);
  const [err, setErr] = useState<string | null>(null);
  const [summary, setSummary] = useState<RevenueSummary | null>(null);
  const [ts, setTs] = useState<TimePoint[]>([]);
  const [byPlan, setByPlan] = useState<LabelCount[]>([]);
  const [userRev, setUserRev] = useState<UserRevenue | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    setErr(null);
    try {
      const range = { from: period.from, to: period.to };
      const [s, t, p, ur] = await Promise.all([
        getRevenueSummary(range),
        getRevenueTimeseries(range, period.granularity),
        getSubscriptionsByPlan(),
        getUserRevenue(),
      ]);
      setSummary(s); setTs(t); setByPlan(p); setUserRev(ur);
    } catch (e: any) {
      setErr(e?.message ?? "Erreur de chargement");
    } finally {
      setLoading(false);
    }
  }, [period]);

  useEffect(() => { load(); }, [load]);

  const churnPct = summary ? `${(summary.churn_rate * 100).toFixed(1)}%` : "—";
  const estMrr = summary?.mrr_cents ?? 0;
  const usrMrr = userRev?.mrr_cents ?? 0;
  const totalMrr = estMrr + usrMrr;

  return (
    <JovialAdminShell title="Revenus" subtitle={period.label} loading={loading} onRefresh={load}>
      <PeriodFilter value={period} onChange={setPeriod} />
      {err ? <Text style={styles.err}>{err}</Text> : null}

      <View style={styles.kpiGrid}>
        <KPIStat label="Revenu total (MRR)" value={formatEuros(totalMrr)} accent="#10B981" icon={<InfoHint text="Revenu mensuel récurrent TOTAL = abonnements établissements (Jovial Pro) + abonnements utilisateurs (Jovial+)." />} />
        <KPIStat label="MRR établissements" value={formatEuros(estMrr)} accent={Pastel.primary} icon={<InfoHint text="Revenu d'abonnement mensuel récurrent des établissements Jovial Pro (abonnements actifs payants × prix mensuel)." />} />
        <KPIStat label="MRR utilisateurs (Jovial+)" value={formatEuros(usrMrr)} accent={usrMrr > 0 ? Pastel.teal : "#9CA3AF"} icon={<InfoHint text={`${userRev?.premium_active ?? 0} abonné(s) Jovial+ actif(s) × 2,99 €/mois.${(userRev?.premium_active ?? 0) === 0 ? " Jovial+ n'est pas encore commercialisé." : ""}`} />} />
        <KPIStat label="ARR total (annualisé)" value={formatEuros(totalMrr * 12)} accent="#8B5CF6" icon={<InfoHint text="ARR = MRR total × 12 (projection annuelle au rythme actuel)." />} />
        <KPIStat label="Abonnements actifs" value={formatInt(summary?.active_count ?? 0)} accent="#6366F1" />
        <KPIStat label="Churn (période)" value={churnPct} accent="#DC2626" icon={<InfoHint text="Churn = taux d'attrition : la part des abonnements perdus (résiliés ou impayés) sur la période. Plus c'est bas, mieux c'est." />} />
        <KPIStat label="Boosts achetés (vol.)" value={formatInt(summary?.boost_volume ?? 0)} accent={Pastel.orange} />
      </View>

      <ChartCard title="Évolution du MRR" subtitle="Revenu mensuel récurrent cumulé">
        <ExportCsvButton rows={ts} columns={REV_TS_CSV_COLUMNS} filenameBase="revenus-mrr" />
        <LineChart
          data={ts.map((p) => ({ label: p.bucket, value: (p.mrr_cents ?? 0) / 100 }))}
          area
          color="#10B981"
          yFormat={(n) => formatCompact(n) + " €"}
        />
      </ChartCard>

      <View style={styles.row}>
        <ChartCard title="MRR par plan" flex={1}>
          <ExportCsvButton rows={byPlan} columns={REV_PLAN_CSV_COLUMNS} filenameBase="revenus-par-plan" />
          <Donut
            data={byPlan.map((d, i) => ({ label: d.label, value: Math.round((d.mrr_cents ?? 0) / 100), color: PALETTE[i % PALETTE.length] }))}
            centerLabel="MRR"
            centerValue={formatEuros(summary?.mrr_cents ?? 0)}
            valueFormat={(n) => formatInt(n) + " €"}
          />
        </ChartCard>
        <ChartCard title="Abonnements par plan" flex={1}>
          <HBarChart data={byPlan.map((d) => ({ label: d.label, value: d.count, color: Pastel.primary }))} />
        </ChartCard>
      </View>
    </JovialAdminShell>
  );
}

const styles = StyleSheet.create({
  kpiGrid: { flexDirection: "row", flexWrap: "wrap", gap: 14 },
  row: { flexDirection: "row", flexWrap: "wrap", gap: 18 },
  err: { color: "#DC2626", fontSize: 13, fontFamily: Font.semiBold },
});
