import { useEffect, useState } from "react";
import { useAuth } from "@/providers/AuthProvider";
import { isPlatformAdmin } from "@/services/admin";

// Renvoie si l'utilisateur connecté est admin plateforme (table platform_admins,
// vérifiée côté serveur via le RPC admin_check). `loading` reste vrai tant que la
// vérification n'est pas tranchée.
export function useIsPlatformAdmin() {
  const { session } = useAuth();
  const userId = session?.user?.id ?? null;
  const [isAdmin, setIsAdmin] = useState(false);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!userId) {
      setIsAdmin(false);
      setLoading(false);
      return;
    }
    let cancelled = false;
    setLoading(true);
    (async () => {
      const ok = await isPlatformAdmin();
      if (cancelled) return;
      setIsAdmin(ok);
      setLoading(false);
    })();
    return () => {
      cancelled = true;
    };
  }, [userId]);

  return { isAdmin, loading };
}
