import { useCallback, useMemo } from "react";

export type MentionUser = {
  user_id: string;
  handle?: string | null;
  firstname?: string | null;
  avatar_url?: string | null;
};

// Token « @xxx » en fin de texte (avant le curseur de fin).
const MENTION_RE = /@([a-zA-Z0-9_.-]*)$/;

/**
 * Autocomplétion @mention réutilisable.
 * @param text  contenu courant du champ
 * @param users candidats (amis / membres) à proposer
 */
export function useMentionAutocomplete(text: string, users: MentionUser[]) {
  const query = useMemo(() => {
    const m = text.match(MENTION_RE);
    return m ? m[1].toLowerCase() : null;
  }, [text]);

  const suggestions = useMemo(() => {
    if (query === null) return [];
    return users
      .filter((u) => !!u.handle)
      .filter((u) => {
        const h = (u.handle ?? "").toLowerCase();
        const n = (u.firstname ?? "").toLowerCase();
        return h.startsWith(query) || n.startsWith(query);
      })
      .slice(0, 5);
  }, [query, users]);

  // Remplace le token @xxx en fin de texte par « @handle ».
  const applyMention = useCallback((current: string, handle: string | null | undefined) => {
    if (!handle) return current;
    // forme callback : évite toute interprétation des motifs $ dans la chaîne de remplacement.
    return current.replace(MENTION_RE, () => `@${handle} `);
  }, []);

  return { query, suggestions, applyMention };
}
