import { useCallback, useEffect, useMemo, useState } from "react";
import {
  ActivityIndicator,
  KeyboardAvoidingView,
  Modal,
  Platform,
  Pressable,
  ScrollView,
  Share,
  StyleSheet,
  Text,
  TextInput,
  View,
} from "react-native";
import { useRouter } from "expo-router";
import { Ionicons } from "@expo/vector-icons";

import { useAuth } from "@/providers/AuthProvider";
import { supabase } from "@/services/supabase";
import { Pastel } from "@/constants/pastel";
import { Font } from "@/constants/typography";
import { UserAvatar } from "@/components/ui/UserAvatar";
import { createGroupPost, listMyGroups } from "@/services/groups";

type Friend = {
  user_id: string;
  handle: string | null;
  firstname: string | null;
  lastname: string | null;
  avatar_url: string | null;
};
type Club = { group_id: number; name: string };
type Tab = "friends" | "clubs" | "profile";

// Feuille de partage in-app : envoie une fiche lieu/événement à un ami (DM),
// dans un de mes clubs, ou sur mon profil. Le fil cible affiche une carte cliquable.
export function ShareToFriendModal({
  visible,
  onClose,
  venueId,
  eventId,
  title,
  defaultMessage,
  onExternalShare,
}: {
  visible: boolean;
  onClose: () => void;
  venueId?: number | null;
  eventId?: number | null;
  title?: string;
  defaultMessage?: string;
  onExternalShare?: () => void;
}) {
  const router = useRouter();
  const { session } = useAuth();
  const userId = session?.user?.id ?? null;

  const [tab, setTab] = useState<Tab>("friends");
  const [friends, setFriends] = useState<Friend[]>([]);
  const [loading, setLoading] = useState(true);
  const [clubs, setClubs] = useState<Club[]>([]);
  const [clubsLoading, setClubsLoading] = useState(false);
  const [clubsLoaded, setClubsLoaded] = useState(false);
  const [query, setQuery] = useState("");
  const [message, setMessage] = useState(defaultMessage ?? "");
  const [sendingTo, setSendingTo] = useState<string | null>(null);
  const [sentTo, setSentTo] = useState<Record<string, boolean>>({});
  const [profileSent, setProfileSent] = useState(false);

  useEffect(() => {
    if (visible) {
      setTab("friends");
      setMessage(defaultMessage ?? "");
      setQuery("");
      setSentTo({});
      setProfileSent(false);
    }
  }, [visible, defaultMessage]);

  useEffect(() => {
    if (!visible || !userId) return;
    let cancelled = false;
    (async () => {
      setLoading(true);
      const [{ data: following }, { data: followers }] = await Promise.all([
        supabase.from("user_follows").select("following_id").eq("follower_id", userId),
        supabase.from("user_follows").select("follower_id").eq("following_id", userId),
      ]);
      const ids = Array.from(
        new Set([
          ...((following ?? []).map((r: any) => String(r.following_id ?? ""))),
          ...((followers ?? []).map((r: any) => String(r.follower_id ?? ""))),
        ])
      ).filter(Boolean);
      if (ids.length === 0) {
        if (!cancelled) { setFriends([]); setLoading(false); }
        return;
      }
      const { data } = await supabase
        .from("profiles")
        .select("user_id, handle, firstname, lastname, avatar_url")
        .in("user_id", ids);
      if (!cancelled) {
        setFriends(((data as Friend[] | null) ?? []).filter((f) => !!f?.user_id));
        setLoading(false);
      }
    })();
    return () => { cancelled = true; };
  }, [visible, userId]);

  // Charge mes clubs à la 1re ouverture de l'onglet Clubs.
  useEffect(() => {
    if (!visible || tab !== "clubs" || !userId || clubsLoaded) return;
    let cancelled = false;
    (async () => {
      setClubsLoading(true);
      try {
        const rows = await listMyGroups(userId);
        if (!cancelled) setClubs(rows.map((r: { group_id: number; name: string }) => ({ group_id: r.group_id, name: r.name })));
      } catch {
        if (!cancelled) setClubs([]);
      } finally {
        if (!cancelled) { setClubsLoading(false); setClubsLoaded(true); }
      }
    })();
    return () => { cancelled = true; };
  }, [visible, tab, userId, clubsLoaded]);

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) return friends;
    return friends.filter((f) =>
      `${f.firstname ?? ""} ${f.lastname ?? ""} ${f.handle ?? ""}`.toLowerCase().includes(q)
    );
  }, [friends, query]);

  const displayName = (f: Friend) => f.firstname?.trim() || f.handle?.trim() || "Ami";
  const bodyText = () => message.trim() || (defaultMessage ?? "");

  const handleSendFriend = useCallback(
    async (friend: Friend) => {
      if (!userId || sendingTo) return;
      setSendingTo(friend.user_id);
      const payload: any = { sender_id: userId, recipient_id: friend.user_id, body: bodyText() || "Ça te dit ?" };
      if (venueId != null) payload.venue_id = venueId;
      if (eventId != null) payload.event_id = eventId;
      const { error } = await supabase.from("chat_messages").insert(payload);
      setSendingTo(null);
      if (!error) setSentTo((p) => ({ ...p, [`f-${friend.user_id}`]: true }));
    },
    [userId, sendingTo, message, defaultMessage, venueId, eventId]
  );

  const handleSendClub = useCallback(
    async (club: Club) => {
      if (!userId || sendingTo) return;
      setSendingTo(`c-${club.group_id}`);
      try {
        await createGroupPost(club.group_id, userId, bodyText() || "Je partage 👀", { venueId, eventId });
        setSentTo((p) => ({ ...p, [`c-${club.group_id}`]: true }));
      } catch {
        // silencieux
      } finally {
        setSendingTo(null);
      }
    },
    [userId, sendingTo, message, defaultMessage, venueId, eventId]
  );

  const handleSendProfile = useCallback(async () => {
    if (!userId || sendingTo) return;
    setSendingTo("profile");
    const { error } = await supabase.from("profile_posts").insert({
      author_id: userId,
      body: bodyText() || null,
      entry_type: "note",
      venue_id: venueId ?? null,
      event_id: eventId ?? null,
    });
    setSendingTo(null);
    if (!error) {
      setProfileSent(true);
      setTimeout(() => onClose(), 1100); // ferme le sheet après le retour visuel
    }
  }, [userId, sendingTo, message, defaultMessage, venueId, eventId, onClose]);

  const handleExternal = () => {
    onClose();
    onExternalShare?.();
  };

  const openConversation = (friend: Friend) => {
    onClose();
    router.push({ pathname: "/profile/chat", params: { friend: friend.user_id } } as any);
  };

  const TABS: { key: Tab; label: string; icon: keyof typeof Ionicons.glyphMap }[] = [
    { key: "friends", label: "Amis", icon: "people-outline" },
    { key: "clubs", label: "Clubs", icon: "color-palette-outline" },
    { key: "profile", label: "Mon profil", icon: "person-outline" },
  ];

  return (
    <Modal visible={visible} transparent animationType="slide" onRequestClose={onClose}>
      <Pressable style={styles.backdrop} onPress={onClose}>
        <KeyboardAvoidingView behavior={Platform.OS === "ios" ? "padding" : undefined} style={styles.kav}>
        <View style={styles.sheet} onStartShouldSetResponder={() => true}>
          <View style={styles.handle} />
          <Text style={styles.title}>{title ?? "Partager"}</Text>

          <TextInput
            value={message}
            onChangeText={setMessage}
            placeholder="Ajoute un mot…"
            placeholderTextColor="#9CA3AF"
            style={styles.msgInput}
            maxLength={200}
          />

          <View style={styles.tabs}>
            {TABS.map((t) => {
              const active = tab === t.key;
              return (
                <Pressable key={t.key} style={[styles.tab, active ? styles.tabActive : null]} onPress={() => setTab(t.key)}>
                  <Ionicons name={t.icon} size={15} color={active ? "#FFFFFF" : Pastel.textMuted} />
                  <Text style={[styles.tabText, active ? styles.tabTextActive : null]}>{t.label}</Text>
                </Pressable>
              );
            })}
          </View>

          {tab === "friends" ? (
            <>
              <View style={styles.search}>
                <Ionicons name="search" size={16} color={Pastel.textMuted} />
                <TextInput
                  value={query}
                  onChangeText={setQuery}
                  placeholder="Rechercher un ami"
                  placeholderTextColor="#9CA3AF"
                  style={styles.searchInput}
                />
              </View>
              {loading ? (
                <ActivityIndicator color={Pastel.primary} style={{ marginVertical: 24 }} />
              ) : filtered.length === 0 ? (
                <Text style={styles.empty}>
                  {friends.length === 0 ? "Ajoute des amis pour leur proposer une sortie." : "Aucun ami trouvé."}
                </Text>
              ) : (
                <ScrollView style={{ maxHeight: 300 }} keyboardShouldPersistTaps="handled">
                  {filtered.map((f) => {
                    const sent = sentTo[`f-${f.user_id}`];
                    return (
                      <Pressable
                        key={f.user_id}
                        style={styles.row}
                        onPress={() => (sent ? openConversation(f) : handleSendFriend(f))}
                        disabled={!!sendingTo}
                      >
                        <UserAvatar uri={f.avatar_url} name={displayName(f)} seed={f.user_id} size={40} />
                        <Text style={styles.rowName} numberOfLines={1}>{displayName(f)}</Text>
                        {sendingTo === f.user_id ? (
                          <ActivityIndicator color={Pastel.primary} />
                        ) : sent ? (
                          <SentPill />
                        ) : (
                          <Ionicons name="send" size={18} color={Pastel.primary} />
                        )}
                      </Pressable>
                    );
                  })}
                </ScrollView>
              )}
            </>
          ) : tab === "clubs" ? (
            clubsLoading ? (
              <ActivityIndicator color={Pastel.primary} style={{ marginVertical: 24 }} />
            ) : clubs.length === 0 ? (
              <Text style={styles.empty}>Tu n'as pas encore de club. Rejoins-en un pour y partager.</Text>
            ) : (
              <ScrollView style={{ maxHeight: 300 }} keyboardShouldPersistTaps="handled">
                {clubs.map((c) => {
                  const sent = sentTo[`c-${c.group_id}`];
                  return (
                    <Pressable
                      key={c.group_id}
                      style={styles.row}
                      onPress={() => (sent ? undefined : handleSendClub(c))}
                      disabled={!!sendingTo || sent}
                    >
                      <View style={styles.clubIcon}>
                        <Ionicons name="people" size={18} color={Pastel.primary} />
                      </View>
                      <Text style={styles.rowName} numberOfLines={1}>{c.name}</Text>
                      {sendingTo === `c-${c.group_id}` ? (
                        <ActivityIndicator color={Pastel.primary} />
                      ) : sent ? (
                        <SentPill />
                      ) : (
                        <Ionicons name="send" size={18} color={Pastel.primary} />
                      )}
                    </Pressable>
                  );
                })}
              </ScrollView>
            )
          ) : (
            <View style={{ paddingVertical: 14 }}>
              <Text style={styles.profileHint}>Partage cette fiche sur ton profil — tes amis la verront dans ton fil.</Text>
              <Pressable
                style={[styles.profileBtn, profileSent ? styles.profileBtnDone : null]}
                onPress={handleSendProfile}
                disabled={!!sendingTo || profileSent}
              >
                {sendingTo === "profile" ? (
                  <ActivityIndicator color="#FFFFFF" />
                ) : profileSent ? (
                  <>
                    <Ionicons name="checkmark" size={18} color="#FFFFFF" />
                    <Text style={styles.profileBtnText}>Partagé sur ton profil</Text>
                  </>
                ) : (
                  <>
                    <Ionicons name="share-social-outline" size={18} color="#FFFFFF" />
                    <Text style={styles.profileBtnText}>Partager sur mon profil</Text>
                  </>
                )}
              </Pressable>
            </View>
          )}

          {onExternalShare ? (
            <Pressable style={styles.externalBtn} onPress={handleExternal}>
              <Ionicons name="share-outline" size={17} color={Pastel.textMuted} />
              <Text style={styles.externalBtnText}>Partager ailleurs (autres apps)…</Text>
            </Pressable>
          ) : null}
        </View>
        </KeyboardAvoidingView>
      </Pressable>
    </Modal>
  );
}

function SentPill() {
  return (
    <View style={styles.sentPill}>
      <Ionicons name="checkmark" size={14} color="#16A34A" />
      <Text style={styles.sentPillText}>Envoyé</Text>
    </View>
  );
}

