import { useCallback, useMemo, useState } from "react";
import {
  ActivityIndicator,
  Alert,
  Dimensions,
  Pressable,
  ScrollView,
  StyleSheet,
  Text,
  View,
} from "react-native";
import { Image } from "expo-image";
import { useLocalSearchParams, useRouter } from "expo-router";
import { useFocusEffect } from "@react-navigation/native";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import { Ionicons } from "@expo/vector-icons";

import { supabase } from "@/services/supabase";
import { useAuth } from "@/providers/AuthProvider";
import { useToast } from "@/providers/ToastProvider";
import { Pastel } from "@/constants/pastel";
import { Font } from "@/constants/typography";

const FALLBACK_COVER =
  "https://images.unsplash.com/photo-1514933651103-005eec06c04b?auto=format&fit=crop&w=1200&q=80";
const CARD_WIDTH = Dimensions.get("window").width - 32;

type Filter = "all" | "going" | "interested" | "reservations";

const FILTERS: { key: Filter; label: string }[] = [
  { key: "all", label: "Tout" },
  { key: "going", label: "J'y vais" },
  { key: "interested", label: "Intéressé" },
  { key: "reservations", label: "Réservations" },
];

type EventItem = {
  id: number;
  status: "interested" | "going";
  hidden: boolean;
  event: { id: number; title: string; starts_at: string; cover_url: string | null; venue_name: string; venue_city: string };
};

type Reservation = {
  id: number;
  starts_at: string;
  status: string | null;
  hidden: boolean;
  game_name: string | null;
  venue_name: string | null;
  venue_logo: string | null;
  venue_id: number | null;
};

function formatDateLong(iso: string) {
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return "";
  return d.toLocaleDateString("fr-FR", { weekday: "long", day: "numeric", month: "long" });
}
function formatTime(iso: string) {
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return "";
  return d.toLocaleTimeString("fr-FR", { hour: "2-digit", minute: "2-digit" });
}

export default function MyOutingsScreen() {
  const router = useRouter();
  const insets = useSafeAreaInsets();
  const { session } = useAuth();
  const { showToast } = useToast();
  const userId = session?.user?.id ?? null;
  const params = useLocalSearchParams<{ filter?: string }>();

  const rawFilter = Array.isArray(params.filter) ? params.filter[0] : params.filter;
  const initialFilter: Filter = (["all", "going", "interested", "reservations"].includes(String(rawFilter ?? ""))
    ? (rawFilter as Filter)
    : "all");

  const [filter, setFilter] = useState<Filter>(initialFilter);
  const [events, setEvents] = useState<EventItem[]>([]);
  const [reservations, setReservations] = useState<Reservation[]>([]);
  const [loading, setLoading] = useState(true);

  const load = useCallback(async () => {
    if (!userId) { setEvents([]); setReservations([]); setLoading(false); return; }
    setLoading(true);
    const now = new Date().toISOString();
    const [{ data: rsvpData }, { data: resData }] = await Promise.all([
      supabase
        .from("rsvps")
        .select("id, status, hidden_from_friends, events ( id, title, starts_at, cover_url, venues ( name, city ) )")
        .eq("user_id", userId)
        .in("status", ["interested", "going"]),
      supabase
        .from("reservations")
        .select("id, starts_at, status, hidden_from_friends, venue_id, games(name), venues(name, logo_url)")
        .eq("user_id", userId)
        .gte("starts_at", now)
        .order("starts_at", { ascending: true }),
    ]);

    const cleanEvents = ((rsvpData as any[] | null) ?? [])
      .map((row) => {
        const ev = row?.events;
        if (!ev?.id || !ev?.starts_at) return null;
        return {
          id: Number(row.id),
          status: row.status === "going" ? "going" : "interested",
          hidden: !!row.hidden_from_friends,
          event: {
            id: Number(ev.id),
            title: String(ev.title ?? ""),
            starts_at: String(ev.starts_at),
            cover_url: ev.cover_url ?? null,
            venue_name: String(ev?.venues?.name ?? "Lieu"),
            venue_city: String(ev?.venues?.city ?? ""),
          },
        } as EventItem;
      })
      .filter((x): x is EventItem => Boolean(x))
      .filter((x) => new Date(x.event.starts_at).getTime() >= Date.now())
      .sort((a, b) => new Date(a.event.starts_at).getTime() - new Date(b.event.starts_at).getTime());

    const cleanRes = ((resData as any[] | null) ?? []).map((row) => ({
      id: Number(row.id),
      starts_at: String(row.starts_at),
      status: row.status ?? null,
      hidden: !!row.hidden_from_friends,
      game_name: String(row?.games?.name ?? "").trim() || null,
      venue_name: String(row?.venues?.name ?? "").trim() || null,
      venue_logo: String(row?.venues?.logo_url ?? "").trim() || null,
      venue_id: row.venue_id ? Number(row.venue_id) : null,
    }));

    setEvents(cleanEvents);
    setReservations(cleanRes);
    setLoading(false);
  }, [userId]);

  useFocusEffect(useCallback(() => { let c = false; (async () => { if (!c) await load(); })(); return () => { c = true; }; }, [load]));

  const visibleEvents = useMemo(() => {
    if (filter === "going") return events.filter((e) => e.status === "going");
    if (filter === "interested") return events.filter((e) => e.status === "interested");
    return events;
  }, [events, filter]);

  const counts = useMemo(() => ({
    all: events.length,
    going: events.filter((e) => e.status === "going").length,
    interested: events.filter((e) => e.status === "interested").length,
    reservations: reservations.length,
  }), [events, reservations]);

  const handleCancel = (id: number, startsAt: string) => {
    if (new Date(startsAt).getTime() - Date.now() <= 24 * 60 * 60 * 1000) {
      Alert.alert("Annulation impossible", "Tu ne peux plus annuler une réservation moins de 24h avant.");
      return;
    }
    Alert.alert("Annuler la réservation ?", "Cette action ne peut pas être annulée.", [
      { text: "Retour", style: "cancel" },
      {
        text: "Annuler",
        style: "destructive",
        onPress: async () => {
          const { error } = await supabase.from("reservations").update({ status: "cancelled" }).eq("id", id);
          if (error) { showToast("Annulation impossible, réessaie", "error"); return; }
          setReservations((prev) => prev.map((r) => (r.id === id ? { ...r, status: "cancelled" } : r)));
          try {
            const { cancelReservationReminders } = await import("@/services/notifications");
            await cancelReservationReminders(id);
          } catch { /* non bloquant */ }
          showToast("Réservation annulée", "success");
        },
      },
    ]);
  };

  const toggleHideEvent = async (rsvpId: number, hidden: boolean) => {
    setEvents((prev) => prev.map((e) => (e.id === rsvpId ? { ...e, hidden } : e)));
    const { error } = await supabase.from("rsvps").update({ hidden_from_friends: hidden }).eq("id", rsvpId);
    if (error) {
      setEvents((prev) => prev.map((e) => (e.id === rsvpId ? { ...e, hidden: !hidden } : e)));
      showToast("Action impossible, réessaie", "error");
      return;
    }
    showToast(hidden ? "Masqué à tes amis" : "Visible par tes amis", "success");
  };

  const toggleHideReservation = async (resId: number, hidden: boolean) => {
    setReservations((prev) => prev.map((r) => (r.id === resId ? { ...r, hidden } : r)));
    const { error } = await supabase.from("reservations").update({ hidden_from_friends: hidden }).eq("id", resId);
    if (error) {
      setReservations((prev) => prev.map((r) => (r.id === resId ? { ...r, hidden: !hidden } : r)));
      showToast("Action impossible, réessaie", "error");
      return;
    }
    showToast(hidden ? "Masqué à tes amis" : "Visible par tes amis", "success");
  };

  const resStatusStyle = (status: string | null) => {
    if (status === "confirmed") return { bg: "#D1FAE5", text: "#065F46", label: "Confirmée" };
    if (status === "cancelled") return { bg: "#FEE2E2", text: "#991B1B", label: "Annulée" };
    return { bg: "#FEF3C7", text: "#92400E", label: "En attente" };
  };

  const showReservations = filter === "reservations";

  return (
    <View style={styles.screen}>
      <View style={[styles.header, { paddingTop: insets.top + 10 }]}>
        <Pressable style={styles.backBtn} onPress={() => router.back()} hitSlop={10}>
          <Ionicons name="chevron-back" size={20} color={Pastel.text} />
        </Pressable>
        <Text style={styles.title}>Mes sorties</Text>
      </View>

      <View style={styles.tabsRow}>
        {FILTERS.map((f) => {
          const active = filter === f.key;
          return (
            <Pressable key={f.key} style={[styles.tab, active && styles.tabActive]} onPress={() => setFilter(f.key)}>
              <Text style={[styles.tabText, active && styles.tabTextActive]} numberOfLines={1}>{f.label}</Text>
              {counts[f.key] > 0 ? (
                <View style={[styles.tabBadge, active && styles.tabBadgeActive]}>
                  <Text style={[styles.tabBadgeText, active && styles.tabBadgeTextActive]}>{counts[f.key]}</Text>
                </View>
              ) : null}
            </Pressable>
          );
        })}
      </View>

      {loading ? (
        <View style={styles.center}><ActivityIndicator color={Pastel.primary} /></View>
      ) : showReservations ? (
        reservations.length === 0 ? (
          <EmptyState
            icon="ticket-outline"
            title="Aucune réservation à venir"
            text="Réserve une activité depuis la fiche d'un lieu."
            cta="Explorer les lieux"
            onPress={() => router.push("/(tabs)/explore" as any)}
          />
        ) : (
          <ScrollView contentContainerStyle={styles.list} showsVerticalScrollIndicator={false}>
            {reservations.map((res) => {
              const st = resStatusStyle(res.status);
              const startsAt = new Date(res.starts_at);
              const canCancel = res.status !== "cancelled" && startsAt.getTime() - Date.now() > 24 * 60 * 60 * 1000;
              return (
                <View key={res.id} style={styles.resCard}>
                  <View style={styles.resHeader}>
                    {res.venue_logo ? (
                      <Image source={{ uri: res.venue_logo }} style={styles.venueLogo} contentFit="contain" transition={120} />
                    ) : (
                      <View style={[styles.venueLogo, styles.venueLogoFallback]}>
                        <Ionicons name="business" size={18} color={Pastel.textMuted} />
                      </View>
                    )}
                    <View style={styles.resHeaderText}>
                      <Text style={styles.activityName}>{res.game_name ?? "Réservation"}</Text>
                      {res.venue_name ? (
                        <Pressable onPress={() => res.venue_id && router.push(`/venue/${res.venue_id}` as any)} style={styles.venueRow}>
                          <Ionicons name="location-outline" size={12} color={Pastel.textMuted} />
                          <Text style={styles.venueName}>{res.venue_name}</Text>
                        </Pressable>
                      ) : null}
                    </View>
                    <View style={[styles.statusPill, { backgroundColor: st.bg }]}>
                      <Text style={[styles.statusText, { color: st.text }]}>{st.label}</Text>
                    </View>
                  </View>
                  <View style={styles.dateBlock}>
                    <Ionicons name="calendar-outline" size={14} color={Pastel.textMuted} />
                    <Text style={styles.dateText} numberOfLines={1}>{formatDateLong(res.starts_at)}</Text>
                    <Text style={styles.timeText}>à {formatTime(res.starts_at)}</Text>
                  </View>
                  {canCancel ? (
                    <Pressable style={styles.cancelBtn} onPress={() => handleCancel(res.id, res.starts_at)}>
                      <Text style={styles.cancelBtnText}>Annuler cette réservation</Text>
                    </Pressable>
                  ) : res.status !== "cancelled" ? (
                    <Text style={styles.noCancel}>Annulation impossible moins de 24h avant</Text>
                  ) : null}
                  <Pressable style={styles.hideToggle} onPress={() => toggleHideReservation(res.id, !res.hidden)} hitSlop={6}>
                    <Ionicons name={res.hidden ? "eye-off-outline" : "eye-outline"} size={14} color={res.hidden ? Pastel.danger : Pastel.textMuted} />
                    <Text style={[styles.hideToggleText, res.hidden && { color: Pastel.danger }]}>{res.hidden ? "Masqué à tes amis" : "Visible par tes amis"}</Text>
                  </Pressable>
                </View>
              );
            })}
          </ScrollView>
        )
      ) : visibleEvents.length === 0 ? (
        <EmptyState
          icon="calendar-outline"
          title="Aucune sortie ici"
          text="Explore la carte et inscris-toi à des événements près de toi."
          cta="Explorer"
          onPress={() => router.push("/(tabs)/explore" as any)}
        />
      ) : (
        <ScrollView contentContainerStyle={styles.list} showsVerticalScrollIndicator={false}>
          {visibleEvents.map((item) => (
            <Pressable key={item.id} style={styles.card} onPress={() => router.push(`/event/${item.event.id}` as any)}>
              <Image source={item.event.cover_url || FALLBACK_COVER} style={styles.cardImage} contentFit="cover" transition={120} cachePolicy="disk" />
              <View style={[styles.rsvpBadge, item.status === "going" ? styles.rsvpBadgeGoing : styles.rsvpBadgeInterested]}>
                <Ionicons name={item.status === "going" ? "checkmark-circle" : "ellipse-outline"} size={12} color={item.status === "going" ? "#FFFFFF" : Pastel.text} />
                <Text style={[styles.rsvpBadgeText, item.status === "going" ? styles.rsvpBadgeTextGoing : styles.rsvpBadgeTextInterested]}>
                  {item.status === "going" ? "J'y vais" : "Intéressé"}
                </Text>
              </View>
              <View style={styles.cardBody}>
                <Text style={styles.cardTitle} numberOfLines={2}>{item.event.title}</Text>
                <View style={styles.cardMeta}>
                  <Ionicons name="calendar-outline" size={13} color={Pastel.textMuted} />
                  <Text style={styles.cardMetaText}>
                    {formatDateLong(item.event.starts_at)} <Text style={styles.cardMetaTime}>à {formatTime(item.event.starts_at)}</Text>
                  </Text>
                </View>
                <View style={styles.cardMeta}>
                  <Ionicons name="location-outline" size={13} color={Pastel.textMuted} />
                  <Text style={styles.cardMetaText} numberOfLines={1}>
                    {[item.event.venue_name, item.event.venue_city].filter(Boolean).join(" · ")}
                  </Text>
                </View>
                <Pressable style={styles.hideToggle} onPress={() => toggleHideEvent(item.id, !item.hidden)} hitSlop={6}>
                  <Ionicons name={item.hidden ? "eye-off-outline" : "eye-outline"} size={14} color={item.hidden ? Pastel.danger : Pastel.textMuted} />
                  <Text style={[styles.hideToggleText, item.hidden && { color: Pastel.danger }]}>{item.hidden ? "Masqué à tes amis" : "Visible par tes amis"}</Text>
                </Pressable>
              </View>
            </Pressable>
          ))}
        </ScrollView>
      )}
    </View>
  );
}

function EmptyState({ icon, title, text, cta, onPress }: { icon: keyof typeof Ionicons.glyphMap; title: string; text: string; cta: string; onPress: () => void }) {
  return (
    <View style={styles.center}>
      <Ionicons name={icon} size={48} color={Pastel.border} />
      <Text style={styles.emptyTitle}>{title}</Text>
      <Text style={styles.emptyText}>{text}</Text>
      <Pressable style={styles.emptyCta} onPress={onPress}>
        <Text style={styles.emptyCtaText}>{cta}</Text>
      </Pressable>
    </View>
  );
}

