import { supabase } from "@/services/supabase";

// Carte « entité partagée » (lieu ou événement) attachée à un message DM,
// un post de club ou un post de profil. Résolveur de métadonnées en lot.
export type SharedCard = {
  kind: "venue" | "event";
  id: number;
  title: string;
  subtitle: string | null;
  image: string | null;
};

export function sharedCardKey(item: { venue_id?: number | null; event_id?: number | null }): string | null {
  if (item.venue_id != null) return `venue-${item.venue_id}`;
  if (item.event_id != null) return `event-${item.event_id}`;
  return null;
}

// Charge en lot les fiches lieu/événement référencées par une liste d'items
// (messages / posts) portant venue_id/event_id. Retourne une map clé->carte.
export async function loadSharedCardMap(
  items: { venue_id?: number | null; event_id?: number | null }[]
): Promise<Record<string, SharedCard>> {
  const venueIds = Array.from(new Set(items.map((m) => m.venue_id).filter((v): v is number => v != null)));
  const eventIds = Array.from(new Set(items.map((m) => m.event_id).filter((v): v is number => v != null)));
  const map: Record<string, SharedCard> = {};
  if (venueIds.length === 0 && eventIds.length === 0) return map;
  if (venueIds.length > 0) {
    const { data } = await supabase.from("venues").select("id, name, city, cover_url, logo_url").in("id", venueIds);
    ((data as any[]) ?? []).forEach((v) => {
      map[`venue-${v.id}`] = {
        kind: "venue",
        id: v.id,
        title: v.name ?? "Lieu",
        subtitle: v.city ?? null,
        image: v.cover_url ?? v.logo_url ?? null,
      };
    });
  }
  if (eventIds.length > 0) {
    const { data } = await supabase.from("events").select("id, title, cover_url, venues(name, city)").in("id", eventIds);
    ((data as any[]) ?? []).forEach((e) => {
      map[`event-${e.id}`] = {
        kind: "event",
        id: e.id,
        title: e.title ?? "Événement",
        subtitle: e.venues?.name ?? null,
        image: e.cover_url ?? null,
      };
    });
  }
  return map;
}
