import { Platform } from "react-native";

// ============================================================================
// Export CSV (back-office admin = web). Délimiteur « ; » (Excel FR), BOM UTF-8
// pour les accents, et neutralisation de l'injection de formules.
// ============================================================================

export type CsvColumn<T> = {
  label: string;
  value: (row: T) => string | number | boolean | null | undefined;
};

function escapeCell(raw: string | number | boolean | null | undefined): string {
  if (raw === null || raw === undefined) return "";
  let s = typeof raw === "boolean" ? (raw ? "Oui" : "Non") : String(raw);
  // Anti-injection (CSV/formula injection) : préfixe les cellules à risque.
  if (/^[=+\-@\t\r]/.test(s)) s = "'" + s;
  // Échappe si la cellule contient le délimiteur, un guillemet ou un saut de ligne.
  if (/[";\n\r]/.test(s)) s = '"' + s.replace(/"/g, '""') + '"';
  return s;
}

export function toCsv<T>(rows: T[], columns: CsvColumn<T>[]): string {
  const header = columns.map((c) => escapeCell(c.label)).join(";");
  const body = rows.map((r) => columns.map((c) => escapeCell(c.value(r))).join(";")).join("\r\n");
  return body ? `${header}\r\n${body}` : header;
}

// Date au format FR (JJ/MM/AAAA) — reconnue comme date par Excel FR.
export function csvDate(s: string | null | undefined): string {
  if (!s) return "";
  const d = new Date(s);
  if (Number.isNaN(d.getTime())) return "";
  const pad = (n: number) => String(n).padStart(2, "0");
  return `${pad(d.getDate())}/${pad(d.getMonth() + 1)}/${d.getFullYear()}`;
}

// Nom de fichier horodaté : jovial-utilisateurs-2026-06-27.csv
export function csvFilename(base: string): string {
  const d = new Date();
  const pad = (n: number) => String(n).padStart(2, "0");
  return `jovial-${base}-${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}.csv`;
}

// Déclenche le téléchargement navigateur (web uniquement). Renvoie false sinon.
export function downloadCsv(filename: string, csv: string): boolean {
  if (Platform.OS !== "web") return false;
  try {
    const doc: any = (globalThis as any).document;
    const BlobCtor: any = (globalThis as any).Blob;
    if (!doc || !BlobCtor) return false;
    const blob = new BlobCtor(["﻿" + csv], { type: "text/csv;charset=utf-8;" });
    const url = URL.createObjectURL(blob);
    const a = doc.createElement("a");
    a.href = url;
    a.download = filename.endsWith(".csv") ? filename : `${filename}.csv`;
    doc.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1500);
    return true;
  } catch {
    return false;
  }
}
