import { useCallback, useEffect, useState } from "react";
import { StyleSheet, Text, View } from "react-native";
import JovialAdminShell from "@/components/ui/JovialAdminShell";
import PeriodFilter, { DEFAULT_PERIOD, Period } from "@/components/ui/PeriodFilter";
import { ChartCard, KPIStat, LineChart, Donut, formatInt, PALETTE } from "@/components/ui/charts";
import { Pastel } from "@/constants/pastel";
import { Font } from "@/constants/typography";
import {
  getEngagementSummary,
  getReservationsTimeseries,
  getReservationsByStatus,
  type EngagementSummary,
  type TimePoint,
  type LabelCount,
} from "@/services/admin";

const STATUS_FR: Record<string, string> = {
  confirmed: "Confirmées", pending: "En attente", cancelled: "Annulées", cancelled_by_venue: "Annulées (étab.)", unknown: "Autre",
};

export default function AdminEngagement() {
  const [period, setPeriod] = useState<Period>(DEFAULT_PERIOD);
  const [loading, setLoading] = useState(true);
  const [err, setErr] = useState<string | null>(null);
  const [summary, setSummary] = useState<EngagementSummary | null>(null);
  const [ts, setTs] = useState<TimePoint[]>([]);
  const [status, setStatus] = useState<LabelCount[]>([]);

  const load = useCallback(async () => {
    setLoading(true);
    setErr(null);
    try {
      const range = { from: period.from, to: period.to };
      const [s, t, st] = await Promise.all([
        getEngagementSummary(range),
        getReservationsTimeseries(range, period.granularity),
        getReservationsByStatus(range),
      ]);
      setSummary(s); setTs(t); setStatus(st);
    } catch (e: any) {
      setErr(e?.message ?? "Erreur de chargement");
    } finally {
      setLoading(false);
    }
  }, [period]);

  useEffect(() => { load(); }, [load]);

  return (
    <JovialAdminShell title="Engagement" subtitle={period.label} loading={loading} onRefresh={load}>
      <PeriodFilter value={period} onChange={setPeriod} />
      {err ? <Text style={styles.err}>{err}</Text> : null}

      <View style={styles.kpiGrid}>
        <KPIStat label="Réservations" value={formatInt(summary?.reservations ?? 0)} accent={Pastel.orange} />
        <KPIStat label="Événements" value={formatInt(summary?.events ?? 0)} accent={Pastel.primary} />
        <KPIStat label="Participations (RSVP)" value={formatInt(summary?.rsvps ?? 0)} accent={Pastel.teal} />
        <KPIStat label="Follows" value={formatInt(summary?.follows ?? 0)} accent="#8B5CF6" />
        <KPIStat label="Favoris" value={formatInt(summary?.favorites ?? 0)} accent="#EC4899" />
        <KPIStat label="Messages" value={formatInt(summary?.messages ?? 0)} accent="#6366F1" />
        <KPIStat label="Posts de clubs" value={formatInt(summary?.club_posts ?? 0)} accent="#10B981" />
        <KPIStat label="Communautés" value={formatInt(summary?.communities ?? 0)} accent="#F59E0B" />
      </View>

      <ChartCard title="Réservations dans le temps" subtitle="Total et annulées (pointillés)">
        <LineChart
          data={ts.map((p) => ({ label: p.bucket, value: p.value }))}
          secondary={ts.map((p) => ({ label: p.bucket, value: p.cancelled ?? 0 }))}
          secondaryColor="#DC2626"
          area
          color={Pastel.orange}
        />
      </ChartCard>

      <View style={styles.row}>
        <ChartCard title="Réservations par statut" flex={1}>
          <Donut data={status.map((d, i) => ({ label: STATUS_FR[d.label] ?? d.label, value: d.count, color: PALETTE[i % PALETTE.length] }))} centerLabel="résa" centerValue={formatInt(status.reduce((s, d) => s + d.count, 0))} />
        </ChartCard>
      </View>
    </JovialAdminShell>
  );
}

const styles = StyleSheet.create({
  kpiGrid: { flexDirection: "row", flexWrap: "wrap", gap: 14 },
  row: { flexDirection: "row", flexWrap: "wrap", gap: 18 },
  err: { color: "#DC2626", fontSize: 13, fontFamily: Font.semiBold },
});
