import { useCallback, useEffect, useState } from "react";
import { StyleSheet, Text, View } from "react-native";
import JovialAdminShell from "@/components/ui/JovialAdminShell";
import { ChartCard, HBarChart } from "@/components/ui/charts";
import { ExportCsvButton } from "@/components/ui/ExportCsvButton";
import { type CsvColumn } from "@/utils/csv";
import { Pastel } from "@/constants/pastel";
import { Font } from "@/constants/typography";
import {
  getUsersByRegion,
  getUsersByDepartment,
  getUsersByCity,
  getEstablishmentsByRegion,
  getEstablishmentsByDepartment,
  getEstablishmentsByCity,
  type LabelCount,
  type DepartmentCount,
} from "@/services/admin";

const DEPT_CSV_COLUMNS: CsvColumn<DepartmentCount>[] = [
  { label: "Code", value: (r) => r.code },
  { label: "Département", value: (r) => r.label },
  { label: "Région", value: (r) => r.region },
  { label: "Nombre", value: (r) => r.count },
];

export default function AdminGeography() {
  const [loading, setLoading] = useState(true);
  const [err, setErr] = useState<string | null>(null);
  const [usrRegion, setUsrRegion] = useState<LabelCount[]>([]);
  const [usrDept, setUsrDept] = useState<DepartmentCount[]>([]);
  const [usrCity, setUsrCity] = useState<LabelCount[]>([]);
  const [estRegion, setEstRegion] = useState<LabelCount[]>([]);
  const [estDept, setEstDept] = useState<DepartmentCount[]>([]);
  const [estCity, setEstCity] = useState<LabelCount[]>([]);

  const load = useCallback(async () => {
    setLoading(true);
    setErr(null);
    try {
      const [ur, ud, uc, er, ed, ec] = await Promise.all([
        getUsersByRegion(),
        getUsersByDepartment(),
        getUsersByCity(15),
        getEstablishmentsByRegion(),
        getEstablishmentsByDepartment(),
        getEstablishmentsByCity(15),
      ]);
      setUsrRegion(ur); setUsrDept(ud); setUsrCity(uc);
      setEstRegion(er); setEstDept(ed); setEstCity(ec);
    } catch (e: any) {
      setErr(e?.message ?? "Erreur de chargement");
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { load(); }, [load]);

  const deptBars = (d: DepartmentCount[], color: string) =>
    d.filter((x) => x.label !== "Non renseigné").slice(0, 15).map((x) => ({ label: `${x.label} (${x.code})`, value: x.count, color }));

  return (
    <JovialAdminShell title="Géographie" subtitle="Répartition par région, département et ville" loading={loading} onRefresh={load}>
      {err ? <Text style={styles.err}>{err}</Text> : null}

      <View style={styles.row}>
        <ChartCard title="Utilisateurs par région" flex={1}>
          <HBarChart data={usrRegion.map((d) => ({ label: d.label, value: d.count, color: Pastel.primary }))} />
        </ChartCard>
        <ChartCard title="Établissements par région" flex={1}>
          <HBarChart data={estRegion.map((d) => ({ label: d.label, value: d.count, color: Pastel.teal }))} />
        </ChartCard>
      </View>

      <View style={styles.row}>
        <ChartCard title="Utilisateurs par département" subtitle="Top 15" flex={1}>
          <ExportCsvButton rows={usrDept} columns={DEPT_CSV_COLUMNS} filenameBase="utilisateurs-par-departement" />
          <HBarChart data={deptBars(usrDept, Pastel.primary)} />
        </ChartCard>
        <ChartCard title="Établissements par département" subtitle="Top 15" flex={1}>
          <ExportCsvButton rows={estDept} columns={DEPT_CSV_COLUMNS} filenameBase="etablissements-par-departement" />
          <HBarChart data={deptBars(estDept, Pastel.teal)} />
        </ChartCard>
      </View>

      <View style={styles.row}>
        <ChartCard title="Top villes — Utilisateurs" flex={1}>
          <HBarChart data={usrCity.map((d) => ({ label: d.label, value: d.count, color: Pastel.primary }))} />
        </ChartCard>
        <ChartCard title="Top villes — Établissements" flex={1}>
          <HBarChart data={estCity.map((d) => ({ label: d.label, value: d.count, color: Pastel.orange }))} />
        </ChartCard>
      </View>
    </JovialAdminShell>
  );
}

const styles = StyleSheet.create({
  row: { flexDirection: "row", flexWrap: "wrap", gap: 18 },
  err: { color: "#DC2626", fontSize: 13, fontFamily: Font.semiBold },
});
