import { useCallback, useRef, useState } from "react";
import {
  View,
  Text,
  Pressable,
  StyleSheet,
  ScrollView,
  useWindowDimensions,
  NativeSyntheticEvent,
  NativeScrollEvent,
} from "react-native";
import { Image } from "expo-image";
import { useRouter } from "expo-router";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import { StatusBar } from "expo-status-bar";
import AsyncStorage from "@react-native-async-storage/async-storage";
import * as Location from "expo-location";

import { Pastel } from "@/constants/pastel";
import { Font } from "@/constants/typography";

// Marine profond UNIQUE = fond de TOUT l'écran ET fond normalisé des 4 illustrations
// (#011A5C, cf. Pastel.navyDeep) -> les images plein cadre se fondent sans aucune
// délimitation. Même couleur que la page d'accueil (welcome.tsx) et l'overlay splash.
const BG = Pastel.navyDeep;

// Onboarding 1ère ouverture (façon TheFork). 4 écrans avec illustrations sur-mesure
// cohérentes (stand-up / palet=clubs / fléchettes / géoloc). Le DERNIER écran (geo)
// demande la permission de localisation puis termine.
const SLIDES = [
  {
    key: "discover",
    image: require("../assets/images/onboard-discover.png"),
    title: "Trouve quoi faire près de chez toi",
    subtitle: "Bars, concerts, soirées, fléchettes, karaoké… toutes les sorties autour de toi, réunies au même endroit.",
  },
  {
    key: "clubs",
    image: require("../assets/images/onboard-near.png"),
    title: "Rejoins un club ou crée le tien",
    subtitle: "Trouve des clubs près de chez toi (pétanque, fléchettes, soirées…) ou crée le tien et réunis ta bande.",
  },
  {
    key: "book",
    image: require("../assets/images/onboard-book.png"),
    title: "Réserve et sors entre amis",
    subtitle: "Réserve une activité, retrouve tes amis et ne rate plus aucune sortie.",
  },
  {
    key: "geo",
    image: require("../assets/images/onboard-geo.png"),
    title: "Active ta position pour commencer",
    subtitle: "Jovial se sert de ta position pour t'afficher les sorties, clubs et événements les plus proches de toi.",
  },
] as const;

export default function OnboardingScreen() {
  const router = useRouter();
  const insets = useSafeAreaInsets();
  const { width } = useWindowDimensions();
  const scrollRef = useRef<ScrollView>(null);
  const [index, setIndex] = useState(0);

  const finish = useCallback(async () => {
    try {
      // Clé versionnée : bump en "_v2" après refonte des illustrations -> l'onboarding
      // se réaffiche une fois pour ceux qui avaient vu l'ancienne version placeholder.
      // DOIT rester identique à la clé lue dans app/_layout.tsx (AuthGate).
      await AsyncStorage.setItem("has_seen_onboarding_v2", "true");
    } catch {}
    router.replace("/welcome");
  }, [router]);

  const goTo = useCallback((i: number) => {
    scrollRef.current?.scrollTo({ x: i * width, animated: true });
    setIndex(i);
  }, [width]);

  const onPrimary = useCallback(async () => {
    // L'écran géoloc (le DERNIER) demande la permission puis termine, quel que soit le résultat.
    if (SLIDES[index].key === "geo") {
      try {
        await Location.requestForegroundPermissionsAsync();
      } catch {}
      finish();
      return;
    }
    if (index >= SLIDES.length - 1) {
      finish();
      return;
    }
    goTo(index + 1);
  }, [index, finish, goTo]);

  const onScrollEnd = (e: NativeSyntheticEvent<NativeScrollEvent>) => {
    setIndex(Math.round(e.nativeEvent.contentOffset.x / width));
  };

  const isGeo = SLIDES[index].key === "geo";
  const primaryLabel = isGeo ? "Activer ma position" : "Continuer";

  return (
    <View style={styles.root}>
      <StatusBar style="light" hidden={false} />

      {/* Passer */}
      <Pressable style={[styles.skipBtn, { top: insets.top + 6 }]} onPress={finish} hitSlop={10}>
        <Text style={styles.skipText}>Passer</Text>
      </Pressable>

      <ScrollView
        ref={scrollRef}
        horizontal
        pagingEnabled
        showsHorizontalScrollIndicator={false}
        onMomentumScrollEnd={onScrollEnd}
        style={styles.pager}
      >
        {SLIDES.map((slide) => (
          <View key={slide.key} style={[styles.slide, { width, paddingTop: insets.top + 44 }]}>
            <View style={styles.illusWrap}>
              <Image source={slide.image} style={styles.illus} contentFit="contain" transition={150} />
            </View>
            <View style={styles.textWrap}>
              <Text style={styles.title}>{slide.title}</Text>
              <Text style={styles.subtitle}>{slide.subtitle}</Text>
            </View>
          </View>
        ))}
      </ScrollView>

      {/* Bas : points + bouton + "Plus tard" (écran géoloc) */}
      <View style={[styles.bottom, { paddingBottom: insets.bottom + 16 }]}>
        <View style={styles.dots}>
          {SLIDES.map((_, i) => (
            <View key={i} style={[styles.dot, i === index ? styles.dotActive : null]} />
          ))}
        </View>

        <Pressable
          style={({ pressed }) => [styles.cta, pressed && { opacity: 0.9 }]}
          onPress={onPrimary}
        >
          <Text style={styles.ctaText}>{primaryLabel}</Text>
        </Pressable>

        {isGeo ? (
          <Pressable onPress={finish} hitSlop={8} style={styles.laterBtn}>
            <Text style={styles.laterText}>Plus tard</Text>
          </Pressable>
        ) : (
          <View style={styles.laterPlaceholder} />
        )}
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  root: { flex: 1, backgroundColor: BG },
  skipBtn: { position: "absolute", right: 18, zIndex: 10, padding: 6 },
  skipText: { color: "rgba(255,255,255,0.75)", fontSize: 14, fontFamily: Font.semiBold, includeFontPadding: false },

  pager: { flex: 1 },
  slide: { flex: 1, alignItems: "center", justifyContent: "flex-start" },
  illusWrap: { flex: 1, width: "100%", alignItems: "center", justifyContent: "center" },
  illus: { width: "100%", height: "100%" },
  textWrap: { alignItems: "center", gap: 12, paddingHorizontal: 28, paddingBottom: 8 },
  title: {
    color: "#FFFFFF",
    fontSize: 27,
    lineHeight: 34,
    fontFamily: Font.extraBold,
    textAlign: "center",
    includeFontPadding: false,
    paddingTop: 2,
  },
  subtitle: {
    color: "rgba(255,255,255,0.78)",
    fontSize: 15,
    lineHeight: 22,
    fontFamily: Font.regular,
    textAlign: "center",
    includeFontPadding: false,
  },

  bottom: { paddingHorizontal: 28, gap: 18 },
  dots: { flexDirection: "row", justifyContent: "center", gap: 8 },
  dot: { width: 7, height: 7, borderRadius: 4, backgroundColor: "rgba(255,255,255,0.3)" },
  dotActive: { backgroundColor: Pastel.teal, width: 22 },
  cta: {
    backgroundColor: Pastel.teal,
    paddingVertical: 16,
    borderRadius: 14,
    alignItems: "center",
    shadowColor: Pastel.teal,
    shadowOpacity: 0.5,
    shadowRadius: 16,
    shadowOffset: { width: 0, height: 6 },
    elevation: 8,
  },
  ctaText: { color: "#FFFFFF", fontSize: 16, fontFamily: Font.extraBold, letterSpacing: 0.3, includeFontPadding: false },
  laterBtn: { alignSelf: "center", paddingVertical: 4 },
  laterText: { color: "rgba(255,255,255,0.6)", fontSize: 14, fontFamily: Font.semiBold, includeFontPadding: false },
  laterPlaceholder: { height: 22 },
});
