import { Pressable, StyleSheet, Text, View, type StyleProp, type ViewStyle } from "react-native";
import { Image } from "expo-image";
import { Ionicons } from "@expo/vector-icons";
import { useRouter } from "expo-router";

import { Pastel } from "@/constants/pastel";
import { Font } from "@/constants/typography";
import type { SharedCard } from "@/services/sharedCards";

// Carte cliquable d'une fiche lieu/événement partagée (DM, club, profil).
export function SharedEntityCard({ card, style }: { card: SharedCard; style?: StyleProp<ViewStyle> }) {
  const router = useRouter();
  const isVenue = card.kind === "venue";
  return (
    <Pressable
      style={[styles.card, style]}
      onPress={() =>
        router.push(
          (isVenue
            ? { pathname: "/venue/[id]", params: { id: String(card.id) } }
            : { pathname: "/event/[id]", params: { id: String(card.id) } }) as any
        )
      }
    >
      {card.image ? (
        <Image source={{ uri: card.image }} style={styles.img} contentFit="cover" transition={120} />
      ) : (
        <View style={[styles.img, styles.imgFallback]}>
          <Ionicons name={isVenue ? "storefront" : "calendar"} size={22} color={Pastel.primary} />
        </View>
      )}
      <View style={styles.body}>
        <View style={[styles.badge, isVenue ? styles.badgeVenue : styles.badgeEvent]}>
          <Text style={[styles.badgeText, { color: isVenue ? Pastel.tealDeep : Pastel.orangeDeep }]}>
            {isVenue ? "LIEU" : "ÉVÉNEMENT"}
          </Text>
        </View>
        <Text style={styles.title} numberOfLines={2}>{card.title}</Text>
        {card.subtitle ? <Text style={styles.sub} numberOfLines={1}>{card.subtitle}</Text> : null}
      </View>
      <Ionicons name="chevron-forward" size={18} color={Pastel.textMuted} />
    </Pressable>
  );
}

const styles = StyleSheet.create({
  card: {
    flexDirection: "row",
    alignItems: "center",
    gap: 12,
    backgroundColor: "#FFFFFF",
    borderRadius: 14,
    padding: 8,
    paddingRight: 10,
    borderWidth: 1,
    borderColor: "#EEF0F4",
    shadowColor: "#0B1020",
    shadowOpacity: 0.06,
    shadowRadius: 10,
    shadowOffset: { width: 0, height: 3 },
    elevation: 1,
  },
  img: { width: 56, height: 56, borderRadius: 12, backgroundColor: "#EEF2F7" },
  imgFallback: { alignItems: "center", justifyContent: "center" },
  body: { flex: 1, minWidth: 0, gap: 3 },
  badge: { alignSelf: "flex-start", borderRadius: 999, paddingHorizontal: 8, paddingVertical: 2 },
  badgeVenue: { backgroundColor: "#D8F0EE" },
  badgeEvent: { backgroundColor: "#FEEAD9" },
  badgeText: { fontSize: 9, fontFamily: Font.extraBold, letterSpacing: 0.5, includeFontPadding: false },
  title: { fontSize: 14, fontFamily: Font.bold, color: Pastel.text, includeFontPadding: false, lineHeight: 18 },
  sub: { fontSize: 11.5, color: Pastel.textMuted, fontFamily: Font.regular, includeFontPadding: false },
});
