import { useEffect, useState } from "react";
import { Pressable, StyleSheet, Text, TextInput, View } from "react-native";
import { Pastel } from "@/constants/pastel";
import { Font } from "@/constants/typography";
import type { Granularity } from "@/services/admin";

export type Period = { from: string; to: string; granularity: Granularity; label: string };

const iso = (d: Date) => d.toISOString().slice(0, 10);
const daysAgo = (n: number) => {
  const d = new Date();
  d.setDate(d.getDate() - n);
  return iso(d);
};
const today = () => iso(new Date());

const PRESETS: { key: string; label: string; build: () => Period }[] = [
  { key: "30j", label: "30 jours", build: () => ({ from: daysAgo(30), to: today(), granularity: "day", label: "30 derniers jours" }) },
  { key: "12s", label: "12 semaines", build: () => ({ from: daysAgo(7 * 12), to: today(), granularity: "week", label: "12 dernières semaines" }) },
  { key: "12m", label: "12 mois", build: () => ({ from: daysAgo(365), to: today(), granularity: "month", label: "12 derniers mois" }) },
  { key: "3a", label: "3 ans", build: () => ({ from: daysAgo(365 * 3), to: today(), granularity: "year", label: "3 dernières années" }) },
];

const isISO = (s: string) => /^\d{4}-\d{2}-\d{2}$/.test(s);

export default function PeriodFilter({ value, onChange }: { value: Period; onChange: (p: Period) => void }) {
  const [custom, setCustom] = useState(false);
  const [from, setFrom] = useState(value.from);
  const [to, setTo] = useState(value.to);
  const [gran, setGran] = useState<Granularity>(value.granularity);
  const [activeKey, setActiveKey] = useState("12m");

  useEffect(() => {
    setFrom(value.from);
    setTo(value.to);
    setGran(value.granularity);
  }, [value.from, value.to, value.granularity]);

  const selectPreset = (p: (typeof PRESETS)[number]) => {
    setCustom(false);
    setActiveKey(p.key);
    onChange(p.build());
  };

  const applyCustom = () => {
    if (!isISO(from) || !isISO(to)) return;
    onChange({ from, to, granularity: gran, label: `${from} → ${to}` });
  };

  return (
    <View style={styles.wrap}>
      <View style={styles.segments}>
        {PRESETS.map((p) => {
          const on = !custom && activeKey === p.key;
          return (
            <Pressable key={p.key} onPress={() => selectPreset(p)} style={[styles.seg, on && styles.segOn]}>
              <Text style={[styles.segTxt, on && styles.segTxtOn]}>{p.label}</Text>
            </Pressable>
          );
        })}
        <Pressable onPress={() => setCustom((v) => !v)} style={[styles.seg, custom && styles.segOn]}>
          <Text style={[styles.segTxt, custom && styles.segTxtOn]}>Perso</Text>
        </Pressable>
      </View>

      {custom ? (
        <View style={styles.customRow}>
          <TextInput value={from} onChangeText={setFrom} placeholder="AAAA-MM-JJ" placeholderTextColor="#9CA3AF" style={styles.dateInput} autoCapitalize="none" />
          <Text style={styles.arrow}>→</Text>
          <TextInput value={to} onChangeText={setTo} placeholder="AAAA-MM-JJ" placeholderTextColor="#9CA3AF" style={styles.dateInput} autoCapitalize="none" />
          <View style={styles.granRow}>
            {(["day", "week", "month", "year"] as Granularity[]).map((g) => (
              <Pressable key={g} onPress={() => setGran(g)} style={[styles.granBtn, gran === g && styles.granBtnOn]}>
                <Text style={[styles.granTxt, gran === g && styles.granTxtOn]}>{g === "day" ? "J" : g === "week" ? "S" : g === "month" ? "M" : "A"}</Text>
              </Pressable>
            ))}
          </View>
          <Pressable onPress={applyCustom} style={styles.applyBtn}>
            <Text style={styles.applyTxt}>OK</Text>
          </Pressable>
        </View>
      ) : null}
    </View>
  );
}

export const DEFAULT_PERIOD: Period = PRESETS[2].build();

const styles = StyleSheet.create({
  wrap: { gap: 10 },
  segments: { flexDirection: "row", gap: 6, flexWrap: "wrap" },
  seg: { paddingHorizontal: 14, paddingVertical: 8, borderRadius: 10, backgroundColor: "#FFFFFF", borderWidth: 1, borderColor: "#E5E7EB" },
  segOn: { backgroundColor: Pastel.primary, borderColor: Pastel.primary },
  segTxt: { color: "#6B7280", fontSize: 13, fontFamily: Font.bold, includeFontPadding: false },
  segTxtOn: { color: "#FFFFFF" },
  customRow: { flexDirection: "row", alignItems: "center", gap: 8, flexWrap: "wrap" },
  dateInput: { backgroundColor: "#FFFFFF", borderWidth: 1, borderColor: "#E5E7EB", borderRadius: 10, paddingHorizontal: 10, paddingVertical: 8, fontSize: 13, color: "#242D41", minWidth: 120, includeFontPadding: false },
  arrow: { color: "#9CA3AF", fontSize: 14 },
  granRow: { flexDirection: "row", gap: 4 },
  granBtn: { width: 30, height: 30, borderRadius: 8, alignItems: "center", justifyContent: "center", backgroundColor: "#FFFFFF", borderWidth: 1, borderColor: "#E5E7EB" },
  granBtnOn: { backgroundColor: Pastel.teal, borderColor: Pastel.teal },
  granTxt: { color: "#6B7280", fontSize: 12, fontFamily: Font.bold, includeFontPadding: false },
  granTxtOn: { color: "#FFFFFF" },
  applyBtn: { backgroundColor: Pastel.navyDeep, borderRadius: 10, paddingHorizontal: 14, paddingVertical: 8 },
  applyTxt: { color: "#FFFFFF", fontSize: 13, fontFamily: Font.bold, includeFontPadding: false },
});
